import { useEffect, useMemo, useRef, useState } from "react";
import { createChart } from "lightweight-charts";
import type {
  CandlestickData,
  IChartApi,
  ISeriesApi,
} from "lightweight-charts";
import {
  canUpdateLastMiniCandle,
  createEntryAwareAutoscaleProvider,
  createLegacyMiniChartOptions,
  createLegacyMiniSeriesOptions,
  hasCompleteMiniChartData,
  toLegacyMiniChartData,
  type EntryAwareYLockState,
  type TradeMiniCandle,
} from "./trade-card-mini-chart-core";
import { useEntryPriceLine } from "./trade-card-mini-chart-price-line";
import { MiniPriceAxisLabels } from "./trade-card-mini-chart-price-labels";
import { useMiniPriceAxisLabels } from "./use-mini-price-axis-labels";
import {
  EntryPill,
  MiniChartStatus,
  MiniChartTopbar,
} from "./trade-card-mini-chart-topbar";
import {
  focusRecentCandles,
  resolveMiniPairIdentity,
} from "./trade-card-mini-chart-viewport";
import {
  scheduleMiniChartVisualReady,
  useMiniChartReadyReset,
  useMiniChartVisualReadyEffect,
} from "./trade-card-mini-chart-visual-ready";
import {
  useEntryAwareYLockSync,
  useMiniChartResize,
  useMiniChartResumeRepaint,
} from "./trade-card-mini-chart-effects";
import { chartDebug } from "@/lib/observability/chart-debug";

export type { TradeMiniCandle } from "./trade-card-mini-chart-core";

type TradeCardMiniChartProps = {
  readonly candles: readonly TradeMiniCandle[];
  readonly currentPrice?: number | undefined;
  readonly direction: "CALL" | "PUT";
  readonly assetSymbol?: string | undefined;
  readonly entryLabel?: string | undefined;
  readonly entryPrice?: number | undefined;
  readonly height?: number | undefined;
  readonly isLoading?: boolean;
  readonly maxCandles?: number;
  readonly minimumCandles?: number;
  readonly onVisualReadyChange?: ((ready: boolean) => void) | undefined;
  readonly visibleCandles?: number;
  readonly fillHorizontalSpace?: boolean;
  readonly fillVerticalSpace?: boolean;
  readonly headerContent?: React.ReactNode | undefined;
  /** When true, esconde a topbar com pílula BTC/USDT + zoom. */
  readonly hideTopbar?: boolean;
  /** When true, hides the bottom-left entry pill (COMPRA/VENDA). */
  readonly hideEntryPill?: boolean;
};

type MiniChartRefs = {
  readonly chart: React.MutableRefObject<IChartApi | null>;
  readonly series: React.MutableRefObject<ISeriesApi<"Candlestick"> | null>;
  readonly paintedCandleCount: React.MutableRefObject<number>;
  readonly paintedData: React.MutableRefObject<readonly CandlestickData[]>;
  readonly paintedVisibleCandles: React.MutableRefObject<number>;
  /** Mutable snapshot consumed by the `autoscaleInfoProvider` closure.
   *  Lives at the refs level so the closure is built ONCE at mount and the
   *  series identity stays stable across re-renders (Y-scale lock fix). */
  readonly yLockState: React.MutableRefObject<{
    current: EntryAwareYLockState;
  }>;
};

const MINI_CHART_HEIGHT = 144;
const MINI_RENDERED_CANDLES = 30;
const MINI_VISIBLE_CANDLES = 15;
// Topbar (pair pill + zoom controls) sits ABOVE the canvas, so reserve space
// to keep the chart from overlapping with the controls — the legacy DEV mirror
// renders the topbar outside the candle area.
const MINI_TOPBAR_HEIGHT = 34;

/** Render a compact TradingView OSS candlestick chart for trade cards.
 *
 * Example: `<TradeCardMiniChart direction="CALL" candles={candles} />`.
 */
// eslint-disable-next-line complexity, max-lines-per-function -- legacy parity rewrite tracked in P4 (Track E chart pre-load)
export function TradeCardMiniChart(
  props: TradeCardMiniChartProps,
): React.JSX.Element {
  const containerRef = useRef<HTMLDivElement>(null);
  const refs = useMiniChartRefs();
  const [isVisualReady, setVisualReady] = useState(false);
  const [chartRevision, setChartRevision] = useState(0);
  const height = props.height ?? MINI_CHART_HEIGHT;
  const fillsVerticalSpace = props.fillVerticalSpace === true;
  const hasHeaderContent = props.headerContent !== undefined;
  const showsTopbar = props.hideTopbar !== true;
  const chromeHeight =
    (hasHeaderContent ? 74 : 0) + (showsTopbar ? MINI_TOPBAR_HEIGHT : 0);
  const chartHeight =
    chromeHeight > 0 && !fillsVerticalSpace
      ? Math.max(80, height - chromeHeight)
      : height;
  const maxCandles = props.maxCandles ?? MINI_RENDERED_CANDLES;
  const minimumCandles = props.minimumCandles ?? maxCandles;
  const visibleCandles = props.visibleCandles ?? MINI_VISIBLE_CANDLES;
  const pairIdentity = resolveMiniPairIdentity(props.assetSymbol);
  const data = useMemo(
    () =>
      toLegacyMiniChartData(props.candles, maxCandles, MINI_RENDERED_CANDLES),
    [props.candles, maxCandles],
  );
  const isCompleteData = hasCompleteMiniChartData(data, minimumCandles);
  const firstDataTime = data[0]?.time;
  const lastDataTime = data[data.length - 1]?.time;
  const lastDataClose = data[data.length - 1]?.close;
  const hasPaintedSnapshot =
    refs.paintedCandleCount.current >= minimumCandles &&
    refs.paintedData.current.length >= minimumCandles;
  // `isCanvasVisible` continua sendo o sinal "tem dado suficiente pra
  // pintar" — exposto via `data-visual-ready` pra outros testes/consumers.
  // R294: opacity-100 é gateada SEPARADAMENTE em `isPaintCommitted` —
  // só libera quando o focus já aplicou (via `isVisualReady` ou snapshot
  // pintado). Antes, isCompleteData liberava opacity ANTES do
  // `focusRecentCandles` rodar, causando o flash inicial com candles
  // desfocados longe da linha de entrada.
  const isCanvasVisible = isVisualReady || hasPaintedSnapshot || isCompleteData;
  const isPaintCommitted = isVisualReady || hasPaintedSnapshot;
  const shouldShowStatus = !hasPaintedSnapshot && !isCompleteData;
  chartDebug("miniChart-data", {
    assetSymbol: props.assetSymbol ?? null,
    propsLength: props.candles.length,
    normalizedLength: data.length,
    minimumCandles,
    maxCandles,
    isCompleteData,
    gateAction: isCompleteData ? "paint" : "skip",
  });
  useMiniChartMount({
    ref: containerRef,
    refs,
    height: chartHeight,
    assetSymbol: props.assetSymbol,
    fillHorizontalSpace: props.fillHorizontalSpace === true,
    fillVerticalSpace: fillsVerticalSpace,
    setChartRevision,
  });
  useMiniChartReadyReset(setVisualReady, isCompleteData, props.assetSymbol);
  useMiniChartVisualReadyEffect(isVisualReady, props.onVisualReadyChange);
  useMiniChartData({
    data,
    chartRevision,
    isCompleteData,
    refs,
    setVisualReady,
    visibleCandles,
  });
  useEntryAwareYLockSync(refs, {
    candles: props.candles,
    currentPrice: props.currentPrice,
    entryPrice: props.entryPrice,
  });
  useMiniChartResize(containerRef, refs, setVisualReady);
  useMiniChartResumeRepaint(containerRef, refs, setVisualReady);
  useEntryPriceLine(refs, props.entryPrice, chartRevision);
  const priceAxisLabels = useMiniPriceAxisLabels({
    chartRevision,
    containerRef,
    currentPrice: props.currentPrice,
    direction: props.direction,
    entryPrice: props.entryPrice,
    isVisible: isCanvasVisible,
    refs,
  });
  return (
    <div
      data-candle-count={isCompleteData ? data.length : 0}
      data-first-candle-time={
        firstDataTime == null ? "" : String(firstDataTime)
      }
      data-last-candle-time={lastDataTime == null ? "" : String(lastDataTime)}
      data-last-candle-close={
        lastDataClose == null ? "" : String(lastDataClose)
      }
      data-max-candles={maxCandles}
      data-min-candles={minimumCandles}
      data-normalized-candle-count={data.length}
      data-pair-label={pairIdentity.pairLabel}
      data-raw-candle-count={props.candles.length}
      data-visual-ready={isCanvasVisible ? "true" : "false"}
      data-testid="active-trade-chart"
      data-fill-horizontal-space={props.fillHorizontalSpace ? "true" : "false"}
      data-fill-vertical-space={fillsVerticalSpace ? "true" : "false"}
      data-visible-candles={visibleCandles}
      className={`flex min-h-0 flex-col overflow-hidden bg-[#050607] ${
        fillsVerticalSpace ? "h-full flex-1" : ""
      }`}
      style={fillsVerticalSpace ? undefined : { height }}
    >
      {/* R267: operador quer ETH/USDT + zoom acima de VENDA/ATUAL (paridade
        legacy). Topbar renderiza ANTES do headerContent, encostado no topo
        do card de trade — não dentro do canvas e não entre os preços e os
        candles. */}
      {showsTopbar ? (
        <MiniChartTopbar
          refs={refs}
          candleCount={data.length}
          pairIdentity={pairIdentity}
          visibleCandles={visibleCandles}
        />
      ) : null}
      {hasHeaderContent ? (
        <div
          className="shrink-0 border-b border-white/5 bg-black/10 px-3 py-2"
          data-testid="active-trade-chart-header"
        >
          {props.headerContent}
        </div>
      ) : null}
      <div
        className="relative isolate min-h-0 flex-1 overflow-hidden"
        data-testid="active-trade-chart-canvas"
      >
        <div
          ref={containerRef}
          className={`absolute inset-0 ${isPaintCommitted ? "opacity-100" : "opacity-0"}`}
        />
        <MiniChartStatus
          isLoading={
            shouldShowStatus &&
            (props.isLoading === true || !isCompleteData || !isVisualReady)
          }
          hasData={!shouldShowStatus && isCanvasVisible}
        />
        <MiniPriceAxisLabels labels={priceAxisLabels} />
        {/* Entry-price line is rendered by `useEntryPriceLine` directly on the
          Lightweight Charts canvas (yellow dashed); the legacy DOM overlay
          `MiniChartEntryLine` was a duplicate visible-only line that
          appeared misaligned vs the chart price axis and was reported by
          the operator as "2 linhas amarelas de entrada que não tem no
          legacy". Removed — canvas line is the single source of truth. */}
        {props.hideTopbar || props.hideEntryPill ? null : (
          <EntryPill
            direction={props.direction}
            entryLabel={props.entryLabel}
          />
        )}
      </div>
    </div>
  );
}

function useMiniChartRefs(): MiniChartRefs {
  const chart = useRef<IChartApi | null>(null);
  const series = useRef<ISeriesApi<"Candlestick"> | null>(null);
  const paintedCandleCount = useRef<number>(0);
  const paintedData = useRef<readonly CandlestickData[]>([]);
  const paintedVisibleCandles = useRef<number>(MINI_VISIBLE_CANDLES);
  const yLockState = useRef<{ current: EntryAwareYLockState }>({
    current: {
      candles: [],
      entryPrice: null,
      lastPrice: null,
      range: null,
    },
  });
  return useMemo(
    () => ({
      chart,
      series,
      paintedCandleCount,
      paintedData,
      paintedVisibleCandles,
      yLockState,
    }),
    [
      chart,
      paintedCandleCount,
      paintedData,
      paintedVisibleCandles,
      series,
      yLockState,
    ],
  );
}

function addMiniSeries(
  chart: IChartApi,
  yLockState: { current: EntryAwareYLockState },
): ISeriesApi<"Candlestick"> {
  // Y-scale lock (28/05/2026): wire the entry-aware autoscale provider here
  // so the series identity stays stable across re-renders. The closure reads
  // the latest entryPrice/lastPrice/candles via the shared ref every paint —
  // see `createEntryAwareAutoscaleProvider` for the algorithm + WHY doc.
  return chart.addCandlestickSeries({
    ...createLegacyMiniSeriesOptions(),
    autoscaleInfoProvider: createEntryAwareAutoscaleProvider(yLockState),
  });
}

function initMiniChart(
  container: HTMLDivElement,
  height: number,
  fillHorizontalSpace: boolean,
  fillVerticalSpace: boolean,
): IChartApi | null {
  if (!document.createElement("canvas").getContext("2d")) return null;
  const rect = container.getBoundingClientRect();
  const width = Math.max(1, container.clientWidth || rect.width);
  const resolvedHeight = fillVerticalSpace
    ? Math.max(1, container.clientHeight || rect.height || height)
    : height;
  return createChart(
    container,
    createLegacyMiniChartOptions(width, resolvedHeight, {
      fillHorizontalSpace,
    }),
  );
}

type MiniChartMountParams = {
  readonly ref: React.RefObject<HTMLDivElement | null>;
  readonly refs: MiniChartRefs;
  readonly height: number;
  readonly fillHorizontalSpace: boolean;
  readonly fillVerticalSpace: boolean;
  readonly assetSymbol: string | undefined;
  readonly setChartRevision: React.Dispatch<React.SetStateAction<number>>;
};

function useMiniChartMount(params: MiniChartMountParams): void {
  const {
    ref,
    refs,
    height,
    assetSymbol,
    fillHorizontalSpace,
    fillVerticalSpace,
    setChartRevision,
  } = params;
  useEffect(() => {
    const container = ref.current;
    if (!container) return;
    const chart = initMiniChart(
      container,
      height,
      fillHorizontalSpace,
      fillVerticalSpace,
    );
    if (!chart) return;
    refs.chart.current = chart;
    refs.series.current = addMiniSeries(chart, refs.yLockState.current);
    setChartRevision((revision) => revision + 1);
    chartDebug("miniChart-mount", {
      assetSymbol: assetSymbol ?? null,
      fillHorizontalSpace,
      fillVerticalSpace,
      height,
      buildId: import.meta.env["VITE_BUILD_ID"] ?? "dev",
    });
    return () => cleanupMiniChart(refs, chart);
  }, [
    assetSymbol,
    fillHorizontalSpace,
    fillVerticalSpace,
    height,
    ref,
    refs,
    setChartRevision,
  ]);
}

function cleanupMiniChart(refs: MiniChartRefs, chart: IChartApi): void {
  refs.chart.current = null;
  refs.series.current = null;
  try {
    chart.remove();
  } catch {
    // lightweight-charts may already be disposed during rapid card transitions.
  }
}

type MiniChartDataParams = {
  readonly chartRevision: number;
  readonly data: readonly CandlestickData[];
  readonly isCompleteData: boolean;
  readonly refs: MiniChartRefs;
  readonly setVisualReady: (ready: boolean) => void;
  readonly visibleCandles: number;
};

type MiniChartDataRefs = {
  readonly lastDataLength: React.MutableRefObject<number>;
  readonly previousData: React.MutableRefObject<readonly CandlestickData[]>;
  readonly previousSeries: React.MutableRefObject<ISeriesApi<"Candlestick"> | null>;
};

function useMiniChartData(params: MiniChartDataParams): void {
  const lastDataLengthRef = useRef<number>(0);
  const previousData = useRef<readonly CandlestickData[]>([]);
  const previousSeries = useRef<ISeriesApi<"Candlestick"> | null>(null);
  const refs: MiniChartDataRefs = {
    lastDataLength: lastDataLengthRef,
    previousData,
    previousSeries,
  };
  useEffect(
    () => syncMiniChartData(params, refs),
    // refs is a stable object built from useRef handles; only param changes
    // should re-trigger the effect.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      params.chartRevision,
      params.data,
      params.isCompleteData,
      params.refs,
      params.setVisualReady,
      params.visibleCandles,
    ],
  );
}

function syncMiniChartData(
  params: MiniChartDataParams,
  refs: MiniChartDataRefs,
): (() => void) | undefined {
  const series = params.refs.series.current;
  if (!series) return undefined;
  const seriesUnchanged = refs.previousSeries.current === series;
  if (!seriesUnchanged) resetMiniChartDataRefs(series, params.refs, refs);
  // Re-run triggered solely by chartRevision (after mount) with identical
  // data must not fire a spurious series.update — the contract is "setData
  // once, then update on live ticks only" (see PENDENCIAS / property test).
  if (seriesUnchanged && refs.previousData.current === params.data)
    return undefined;
  if (!params.isCompleteData || params.data.length === 0) {
    clearIncompleteMiniChart(refs.lastDataLength);
    return undefined;
  }
  return applyMiniChartPaint(params, refs);
}

function resetMiniChartDataRefs(
  series: ISeriesApi<"Candlestick">,
  parentRefs: MiniChartRefs,
  refs: MiniChartDataRefs,
): void {
  refs.previousSeries.current = series;
  refs.previousData.current = [];
  refs.lastDataLength.current = 0;
  parentRefs.paintedCandleCount.current = 0;
  parentRefs.paintedData.current = [];
}

function applyMiniChartPaint(
  params: MiniChartDataParams,
  refs: MiniChartDataRefs,
): (() => void) | undefined {
  const action = decideMiniChartAction(
    refs.previousData.current,
    params.data,
    refs.lastDataLength.current,
  );
  const isFirstPaint = refs.lastDataLength.current === 0;
  if (action === "setData" && isFirstPaint) params.setVisualReady(false);
  applyMiniChartAction(action, params.refs, params.data, params.visibleCandles);
  chartDebug("miniChart-paint", {
    action,
    incoming: params.data.length,
    previous: refs.previousData.current.length,
    isCompleteData: params.isCompleteData,
  });
  refs.previousData.current = params.data;
  refs.lastDataLength.current = params.data.length;
  if (action === "setData" && isFirstPaint)
    return scheduleMiniChartVisualReady(params.setVisualReady);
  if (action === "setData") params.setVisualReady(true);
  return undefined;
}

function clearIncompleteMiniChart(
  lastDataLengthRef: React.MutableRefObject<number>,
): void {
  if (lastDataLengthRef.current === 0) return;
  chartDebug("miniChart-clear-incomplete", { action: "hold" });
}

type MiniChartAction = "setData" | "update";

function decideMiniChartAction(
  previous: readonly CandlestickData[],
  next: readonly CandlestickData[],
  lastDataLength: number,
): MiniChartAction {
  if (lastDataLength === 0) return "setData";
  if (canUpdateLastMiniCandle(previous, next)) return "update";
  if (isMiniChartTickAppend(previous, next)) return "update";
  return "setData";
}

function isMiniChartTickAppend(
  previous: readonly CandlestickData[],
  next: readonly CandlestickData[],
): boolean {
  if (previous.length === 0 || next.length !== previous.length + 1)
    return false;
  for (let index = 0; index < previous.length; index += 1) {
    const a = previous[index];
    const b = next[index];
    if (!a || !b || a.time !== b.time || a.close !== b.close) return false;
  }
  return true;
}

function applyMiniChartAction(
  action: MiniChartAction,
  refs: MiniChartRefs,
  data: readonly CandlestickData[],
  visibleCandles: number,
): void {
  const series = refs.series.current;
  if (!series) return;
  refs.paintedCandleCount.current = data.length;
  refs.paintedData.current = data;
  refs.paintedVisibleCandles.current = visibleCandles;
  if (action === "update") {
    series.update(data[data.length - 1]!);
    return;
  }
  // PENDENCIAS contract: first paint is a single `setData` of the historic
  // window. Live ticks call `update()` later. The legacy `setData + update`
  // reinforce pair caused a single-candle visual mount on cold start —
  // tracked in trade-card-mini-chart.legacyPaint/property tests.
  series.setData([...data]);
  focusRecentCandles(
    refs.chart.current,
    data,
    visibleCandles,
    MINI_VISIBLE_CANDLES,
  );
  window.requestAnimationFrame(() =>
    focusRecentCandles(
      refs.chart.current,
      data,
      visibleCandles,
      MINI_VISIBLE_CANDLES,
    ),
  );
}

// Resize, resume-repaint, Y-lock sync e refocus extraídos para
// `trade-card-mini-chart-effects.ts` (max-lines lint cap 600).

