// R250: IA pill on the status ribbon now opens a Basic/Pro dropdown
// (legacy `ai-mode-controls.tsx` parity). Selecting Pro without
// entitlement fires the upsell callback; selecting Basic always succeeds.
// Selecting an already-active mode is a no-op.

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type Dispatch,
  type ReactNode,
  type ReactPortal,
  type SetStateAction,
} from "react";
import { createPortal } from "react-dom";
import { ChevronDown, Crown, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils/cn";
import {
  resolveAiOverlayPlacement,
  type RectSnapshot,
} from "@/features/robot/lib/resolveAiOverlayPlacement";
import type { VisualViewportSnapshot } from "@/features/robot/lib/resolveViewportMetrics";

export type AiModeOption = "basic" | "pro";

type AiModeStatusDropdownProps = {
  readonly current: AiModeOption;
  readonly hasPro: boolean;
  readonly onSelectMode: (mode: AiModeOption) => void;
  /** Fired when user picks PRO without entitlement (open upsell sheet). */
  readonly onUpsellPro: () => void;
  readonly busy?: boolean;
  readonly disabled?: boolean;
};

type AiMenuLayout = {
  readonly left: number;
  readonly maxHeight: number;
  readonly placement: "above" | "below";
  readonly top: number;
};

const OVERLAY_MARGIN_PX = 8;

/** Inline dropdown rendered inside the FlowControlPanel IA chip.
 *
 * Example: `<AiModeStatusDropdown current="basic" hasPro={false} onSelectMode={...} onUpsellPro={...} />`
 */
export function AiModeStatusDropdown(
  props: AiModeStatusDropdownProps,
): React.JSX.Element {
  const [isOpen, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  const layout = useAiMenuLayout(isOpen, rootRef, overlayRef);
  useDismissAiMenu(rootRef, overlayRef, () => setOpen(false), isOpen);
  const handleSelect = (mode: AiModeOption): void => {
    setOpen(false);
    if (mode === props.current) return;
    if (mode === "pro" && !props.hasPro) {
      props.onUpsellPro();
      return;
    }
    props.onSelectMode(mode);
  };
  return (
    <div ref={rootRef} className="relative z-20 w-full min-w-0">
      <AiPillTrigger
        busy={props.busy === true}
        current={props.current}
        disabled={props.disabled === true}
        isOpen={isOpen}
        onClick={() => setOpen((prev) => !prev)}
      />
      {isOpen ? (
        <AiMenuPortal layout={layout} overlayRef={overlayRef}>
          <AiModeMenu
            current={props.current}
            hasPro={props.hasPro}
            onSelect={handleSelect}
          />
        </AiMenuPortal>
      ) : null}
    </div>
  );
}

function useDismissAiMenu(
  triggerRef: React.RefObject<HTMLElement | null>,
  overlayRef: React.RefObject<HTMLElement | null>,
  onDismiss: () => void,
  enabled: boolean,
): void {
  useEffect(() => {
    if (!enabled) return;
    const onPointerDown = (event: MouseEvent): void => {
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) return;
      if (overlayRef.current?.contains(target)) return;
      onDismiss();
    };
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === "Escape") onDismiss();
    };
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [enabled, onDismiss, overlayRef, triggerRef]);
}

function AiPillTrigger(props: {
  readonly busy: boolean;
  readonly current: AiModeOption;
  readonly disabled: boolean;
  readonly isOpen: boolean;
  readonly onClick: () => void;
}): React.JSX.Element {
  const label = props.current === "pro" ? "PRO" : "BASIC";
  return (
    <button
      type="button"
      disabled={props.disabled}
      onClick={props.onClick}
      data-testid="flow-status-ai-cell"
      data-chip-tone={props.current === "pro" ? "ia-pro" : "ia-basic"}
      aria-label="Selecionar modo de IA"
      aria-busy={props.busy ? "true" : undefined}
      aria-expanded={props.isOpen}
      aria-haspopup="menu"
      className={cn(
        // R277: justify-center no mobile (era justify-between). Como Sparkles
        // e ChevronDown estão `hidden sm:block`, sobra só o <span>BASIC</span>
        // como flex item — justify-between com 1 item joga no flex-start
        // (esquerda). Centralizamos no mobile e voltamos pra between em sm+.
        "inline-flex h-8 w-full max-w-full min-w-0 items-center justify-center gap-0.5 overflow-hidden rounded-full border px-1 py-1 text-left transition sm:h-9 sm:justify-between sm:px-2",
        "w-full whitespace-nowrap text-[7px] font-semibold uppercase leading-[1.05] tracking-[0.03em] sm:text-[8px]",
        // Issue #186: the selector card keeps the larger Pro glow; this
        // compact status chip must use inset-only light or S8 shows bleed.
        props.current === "pro"
          ? "border-fuchsia-400/22 bg-fuchsia-500/10 text-fuchsia-100 shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] hover:border-fuchsia-300/35 hover:bg-fuchsia-500/12"
          : "border-cyan-300/16 bg-[linear-gradient(180deg,rgba(34,211,238,0.08),rgba(12,20,27,0.84))] text-cyan-50/92 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] hover:border-cyan-200/22 hover:bg-[linear-gradient(180deg,rgba(103,232,249,0.11),rgba(12,20,27,0.88))]",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fuchsia-300/55",
      )}
    >
      {props.current === "pro" ? (
        // Issue #170 (28/05/2026): coroa fuchsia ESTÁTICA no chip da statusbar
        // (paridade legacy: o pulse fica só na linha do dropdown, NUNCA na
        // pílula do statusbar). Operador confirmou: "n e pra pulsar no status
        // bar a ia pro, comportamento igual legacy".
        <Crown className="hidden h-2 w-2 shrink-0 text-fuchsia-400 drop-shadow-[0_0_4px_rgba(217,70,239,0.55)] sm:block" />
      ) : (
        <Sparkles className="hidden h-2 w-2 shrink-0 text-cyan-300/90 sm:block" />
      )}
      <span className="shrink-0">{label}</span>
      <ChevronDown className="hidden h-2 w-2 shrink-0 opacity-60 sm:block" />
    </button>
  );
}

function useAiMenuLayout(
  isOpen: boolean,
  triggerRef: React.RefObject<HTMLElement | null>,
  overlayRef: React.RefObject<HTMLElement | null>,
): AiMenuLayout | null {
  const [layout, setLayout] = useState<AiMenuLayout | null>(null);
  useEffect(() => {
    if (!isOpen) {
      setLayout(null);
      return;
    }
    return observeAiMenuLayout(triggerRef, overlayRef, setLayout);
  }, [isOpen, overlayRef, triggerRef]);
  return layout;
}

function observeAiMenuLayout(
  triggerRef: React.RefObject<HTMLElement | null>,
  overlayRef: React.RefObject<HTMLElement | null>,
  setLayout: Dispatch<SetStateAction<AiMenuLayout | null>>,
): () => void {
  let frameId = 0;
  const update = (): void => {
    window.cancelAnimationFrame(frameId);
    frameId = window.requestAnimationFrame(() => {
      const next = measureAiMenuLayout(triggerRef.current, overlayRef.current);
      if (next) setLayout(next);
    });
  };
  update();
  window.addEventListener("resize", update);
  window.addEventListener("scroll", update, true);
  window.visualViewport?.addEventListener("resize", update);
  window.visualViewport?.addEventListener("scroll", update);
  return () => {
    window.cancelAnimationFrame(frameId);
    window.removeEventListener("resize", update);
    window.removeEventListener("scroll", update, true);
    window.visualViewport?.removeEventListener("resize", update);
    window.visualViewport?.removeEventListener("scroll", update);
  };
}

function measureAiMenuLayout(
  trigger: HTMLElement | null,
  overlay: HTMLElement | null,
): AiMenuLayout | null {
  if (!trigger || !overlay) return null;
  return resolveAiMenuLayout(
    trigger.getBoundingClientRect(),
    overlay.getBoundingClientRect(),
  );
}

function resolveAiMenuLayout(trigger: DOMRect, overlay: DOMRect): AiMenuLayout {
  const width = Math.max(overlay.width, 158);
  const height = Math.max(overlay.height, 88);
  const placement = resolveAiOverlayPlacement({
    overlayHeight: height,
    overlayWidth: width,
    triggerRect: rectSnapshot(trigger),
    visualViewport: visualViewportSnapshot(),
  });
  return {
    left: placement.left,
    maxHeight: maxAiMenuHeight(trigger, visualViewportSnapshot()),
    placement: placement.transform === "flip-up" ? "above" : "below",
    top: placement.top,
  };
}

function maxAiMenuHeight(
  anchor: DOMRect,
  viewport: VisualViewportSnapshot | null,
): number {
  const bottom =
    (viewport?.offsetTop ?? 0) + (viewport?.height ?? window.innerHeight);
  return Math.max(96, bottom - anchor.bottom - OVERLAY_MARGIN_PX);
}

function rectSnapshot(rect: DOMRect): RectSnapshot {
  return {
    height: rect.height,
    left: rect.left,
    top: rect.top,
    width: rect.width,
  };
}

function visualViewportSnapshot(): VisualViewportSnapshot | null {
  const viewport = window.visualViewport;
  if (!viewport) return null;
  return {
    height: viewport.height,
    offsetLeft: viewport.offsetLeft,
    offsetTop: viewport.offsetTop,
    scale: viewport.scale,
    width: viewport.width,
  };
}

function AiMenuPortal(props: {
  readonly children: ReactNode;
  readonly layout: AiMenuLayout | null;
  readonly overlayRef: React.RefObject<HTMLDivElement | null>;
}): ReactPortal | null {
  if (typeof document === "undefined") return null;
  return createPortal(
    <div
      ref={props.overlayRef}
      data-testid="flow-status-ai-menu"
      data-placement={props.layout?.placement ?? "below"}
      role="menu"
      style={aiMenuPortalStyle(props.layout)}
      className="z-[80] overflow-y-auto"
    >
      {props.children}
    </div>,
    document.body,
  );
}

function aiMenuPortalStyle(layout: AiMenuLayout | null): CSSProperties {
  return {
    left: layout?.left ?? OVERLAY_MARGIN_PX,
    maxHeight: layout?.maxHeight ?? 320,
    position: "fixed",
    top: layout?.top ?? OVERLAY_MARGIN_PX,
    visibility: layout ? "visible" : "hidden",
  };
}

function AiModeMenu(props: {
  readonly current: AiModeOption;
  readonly hasPro: boolean;
  readonly onSelect: (mode: AiModeOption) => void;
}): React.JSX.Element {
  return (
    <div className="min-w-[158px] rounded-[14px] border border-white/8 bg-[#0A0F18]/96 p-1 shadow-[0_14px_40px_rgba(0,0,0,0.5)] ring-1 ring-cyan-400/8 backdrop-blur-xl">
      <AiModeOptionRow
        active={props.current === "basic"}
        icon="basic"
        label="IA Basic"
        testId="flow-status-ai-option-basic"
        onClick={() => props.onSelect("basic")}
      />
      <AiModeOptionRow
        active={props.current === "pro"}
        icon={props.hasPro ? "pro-entitled" : "pro-locked"}
        label={props.hasPro ? "IA Pro" : "IA Pro · Comprar"}
        testId="flow-status-ai-option-pro"
        onClick={() => props.onSelect("pro")}
      />
    </div>
  );
}

function AiModeOptionRow(props: {
  readonly active: boolean;
  readonly icon: "basic" | "pro-entitled" | "pro-locked";
  readonly label: string;
  readonly onClick: () => void;
  readonly testId: string;
}): React.JSX.Element {
  const isProRow = props.icon !== "basic";
  return (
    <button
      type="button"
      role="menuitem"
      onClick={props.onClick}
      data-testid={props.testId}
      className={cn(
        "flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left text-[11px] font-semibold uppercase tracking-[0.04em]",
        // Issue #170 (28/05/2026): linha PRO no dropdown ganha gradient
        // fuchsia quando hover/ativa (paridade legacy `ai-model-selector-
        // parts.tsx:42`). Linha BASIC mantém o tom branco neutro.
        props.active && isProRow
          ? "bg-[linear-gradient(135deg,rgba(120,52,255,0.18),rgba(217,70,239,0.14))] border border-fuchsia-400/38 text-fuchsia-50 shadow-[0_14px_30px_rgba(217,70,239,0.18)]"
          : props.active
            ? "bg-white/10 text-white"
            : isProRow
              ? "text-fuchsia-100/80 hover:bg-[linear-gradient(135deg,rgba(120,52,255,0.12),rgba(217,70,239,0.08))] hover:text-fuchsia-50"
              : "text-white/70 hover:bg-white/5 hover:text-white",
      )}
    >
      <AiModeOptionIcon icon={props.icon} />
      <span>{props.label}</span>
    </button>
  );
}

function AiModeOptionIcon(props: {
  readonly icon: "basic" | "pro-entitled" | "pro-locked";
}): React.JSX.Element {
  if (props.icon === "pro-entitled") {
    return (
      <Crown className="h-3.5 w-3.5 text-fuchsia-400 motion-safe:animate-pulse" />
    );
  }
  if (props.icon === "pro-locked") {
    return <Crown className="h-3.5 w-3.5 text-fuchsia-400/65" />;
  }
  return <Sparkles className="h-3.5 w-3.5 text-cyan-300" />;
}

