import { useState } from "react";
import { Power, Sparkles } from "lucide-react";
import { ROBOT_COPY } from "@/lib/copy";
import {
  markInteractionFeedback,
  markInteractionReady,
  markInteractionStart,
} from "@/lib/perf/interactionMarks";
import { cn } from "@/lib/utils/cn";
import { PauseConfirmModal } from "../PauseConfirmModal";
import { AiModeStatusDropdown } from "./AiModeStatusDropdown";
import { StopBudgetRow } from "./FlowStopBudgetRow";
import type { RobotVisualFlowStage } from "./robot-visual-flow";

export type RobotFlowStopBudget = {
  /** Daily profit since 00:00 America/Sao_Paulo; kept for backend/debug context. */
  readonly dailyProfitCents: number;
  /** Loss cap in cents, derived from `runtimeBalanceCents * stopLossPercent`. */
  readonly stopLossCents: number;
  /** Win cap in cents, derived from `runtimeBalanceCents * stopWinPercent`. */
  readonly stopWinCents: number;
  /** Live session profit (positive = winning, negative = losing) in cents. */
  readonly sessionProfitCents: number;
};

/** 4-column ribbon mirrored from the legacy DEV flow: STATUS · TOKENS · PLANO · IA.
 *  #48 ν-CHIP-TOK: `tokensLabel === null` hides the chip entirely (legacy
 *  parity with `resolveInlineTokenLabel` returning null). */
export type RobotFlowStatusBar = {
  readonly tokensLabel: string | null;
  readonly planLabel: string;
  readonly aiLabel: string;
  readonly stopRequested?: boolean;
  /** R262: when `stopRequested === true` and this callback is provided,
   *  clicking the power button fires this directly (bypassing the confirm
   *  modal) to cancel the pending shutdown — paridade legacy
   *  `../quartel-bot/.../stop-button.tsx:9-12`. */
  readonly onCancelStop?: () => void;
  /** Optional click handler for the IA dropdown trigger (used as PRO upsell
   *  trigger when {@link aiSelector} is set). */
  readonly onAiClick?: () => void;
  /** Optional click handler for the TOKENS cell (DEV parity: opens token offers). */
  readonly onTokensClick?: () => void;
  /** Optional click handler for the PLANO cell (DEV parity: opens plan offers). */
  readonly onPlanClick?: () => void;
  /** Optional dropdown control: when present the IA cell becomes a Basic/Pro
   *  picker (legacy ai-mode-controls parity). When absent the cell stays a
   *  read-only pill / single onAiClick action. */
  readonly aiSelector?: AiSelectorState;
};

export type AiSelectorState = {
  readonly current: "basic" | "pro";
  readonly hasPro: boolean;
  readonly onSelect: (mode: "basic" | "pro") => void;
  readonly busy?: boolean;
  readonly disabled?: boolean;
};

const FLOW_STAGE_STATUS_LABEL: Record<RobotVisualFlowStage, string> = {
  idle: "PRONTO",
  analyzing: "ANÁLISE",
  signal: "SINAL",
  executing: "TRADE",
  active_trade: "TRADE",
  result: "RESULTADO",
  stopped: "PARADO",
};

// R300 (issue #176-3, 28/05/2026): Samsung S8 360×740 hardening. Operador viu
// "PRO" truncado e demais chips apertados no S8 real. As larguras anteriores
// foram calibradas pra iPhone 14 (390 wide); 360 deixava ~30px a menos no
// total disponível. Tuning:
//   - IA: 44 → 48 base (+4px de respiração pro "PRO" no chip-dropdown que
//     usa text-[7px] tracking-[0.03em] — 4px adicionais cobrem o
//     letter-spacing acumulado + paddings internos sem cortar texto).
//   - Demais chips ganham um tier `min-[360px]:` redondo pra escalar entre
//     320 (iPhone SE) e 375 (iPhone 14 Pro) sem saltos.
//   - `sm:` larguras reduzidas em ~10-15px (operador: "diminuir sm: pra
//     não desperdiçar espaço no desktop e ribbon ficar proporcional ao
//     painel 430px max-w").
//
// NÃO MEXER nos handlers handleClick/handleConfirm/onCancelStop (linhas
// ~155-170 abaixo) — escopo da issue #175-A (markInteractionReady).
const AI_STATUS_CELL_WIDTH_CLASS = "w-[48px] min-[375px]:w-[52px] sm:w-[64px]";

export function FlowControlPanel(props: {
  readonly stage: RobotVisualFlowStage;
  readonly statusBar: RobotFlowStatusBar | undefined;
  readonly stopBudget: RobotFlowStopBudget | undefined;
  readonly onStop: (() => void) | undefined;
}): React.JSX.Element | null {
  if (!props.statusBar && !props.stopBudget) return null;
  if (props.stage === "stopped") return null;
  return (
    <div
      data-testid="flow-control-panel"
      data-pill-root
      className="sticky top-2 z-40 mx-auto h-[100px] w-full max-w-[430px] overflow-hidden rounded-[1.75rem] border border-white/[0.06] bg-[#0A0F18]/90 px-2.5 py-2 shadow-[0_16px_36px_rgba(0,0,0,0.38)] ring-1 ring-white/[0.03] sm:px-2"
    >
      <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-[20px]">
        <div className="absolute inset-x-8 top-0 h-px bg-gradient-to-r from-transparent via-cyan-300/14 to-transparent" />
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(34,211,238,0.05),transparent_40%),radial-gradient(circle_at_bottom_left,rgba(20,184,166,0.03),transparent_34%)]" />
      </div>
      <div className="relative z-10">
        <FlowStatusBar
          stage={props.stage}
          bar={props.statusBar}
          onStop={props.onStop}
        />
        <StopBudgetRow stage={props.stage} budget={props.stopBudget} />
      </div>
    </div>
  );
}

function FlowStatusBar(props: {
  readonly stage: RobotVisualFlowStage;
  readonly bar: RobotFlowStatusBar | undefined;
  readonly onStop: (() => void) | undefined;
}): React.JSX.Element | null {
  if (!props.bar) return null;
  if (props.stage === "stopped") return null;
  return (
    <div
      data-testid="flow-status-bar"
      className="flex h-[50px] w-full items-end gap-1.5"
    >
      <FlowStatusMetrics stage={props.stage} bar={props.bar} />
      <FlowStatusPowerButton
        onStop={props.onStop}
        stopRequested={props.bar.stopRequested === true}
        onCancelStop={props.bar.onCancelStop}
        active={props.stage !== "idle"}
      />
    </div>
  );
}

// R250: status-bar power button now opens a confirmation modal before
// stopping the robot — operator wants the same "vai parar as próximas trades"
// warning the legacy DEV shows. The PauseConfirmModal component already
// exists; we just wire it here so the button can't trip an accidental stop.
//
// R262: when `stopRequested === true` AND `onCancelStop` is provided, the
// click bypasses the modal and fires `onCancelStop` directly — paridade
// com `../quartel-bot/...stop-button.tsx`, onde o segundo clique cancela
// o desligamento agendado em vez de re-abrir o confirm.
function FlowStatusPowerButton(props: {
  readonly active: boolean;
  readonly onStop: (() => void) | undefined;
  readonly onCancelStop: (() => void) | undefined;
  readonly stopRequested: boolean;
}): React.JSX.Element {
  const interactive = props.onStop != null;
  const className = powerButtonClassName(
    interactive,
    props.stopRequested,
    props.active,
  );
  const [isConfirmOpen, setConfirmOpen] = useState(false);
  if (!interactive) {
    return (
      <span data-testid="flow-status-power" className={className}>
        <PowerIcon active={props.active} />
      </span>
    );
  }
  const handleClick = (): void => {
    markInteractionStart("robot-stop");
    if (props.stopRequested && props.onCancelStop) {
      props.onCancelStop();
      markInteractionFeedback("robot-stop", { action: "cancel-scheduled" });
      markInteractionReady("robot-stop", { action: "cancel-scheduled" });
      return;
    }
    setConfirmOpen(true);
    markInteractionFeedback("robot-stop", { surface: "confirm-modal" });
    markInteractionReady("robot-stop", { surface: "confirm-modal" });
  };
  // #175 PARTE A: handleConfirm fires when the user clicks Confirmar inside
  // PauseConfirmModal. The modal itself instruments `robot-pause-confirm`
  // (modal-level paint); here we instrument `robot-stop-confirm` (the
  // outer orchestration: close modal + dispatch stop). Required order:
  //   1. markInteractionStart  → opens perf window for the outer event.
  //   2. setConfirmOpen(false) → modal closes sync.
  //   3. markInteractionFeedback → frame-0 paint signal (modal gone).
  //   4. props.onStop?.()      → fire-and-forget DELETE (no await).
  //   5. markInteractionReady  → optimistic ready marker.
  const handleConfirm = (): void => {
    markInteractionStart("robot-stop-confirm");
    setConfirmOpen(false);
    markInteractionFeedback("robot-stop-confirm", { pending: true });
    props.onStop?.();
    markInteractionReady("robot-stop-confirm", { optimistic: true });
  };
  return (
    <>
      <button
        type="button"
        onClick={handleClick}
        data-testid="flow-status-power-button"
        aria-label={resolvePowerButtonLabel(
          props.stopRequested,
          props.onCancelStop != null,
        )}
        className={className}
      >
        {/* #69 C-3: canonical `robot-stop-button` testid; legacy stays on the
         *  outer button (parallel-login.ts#waitForBotSessionIdle clicks this). */}
        <span data-testid="robot-stop-button" className="contents">
          <PowerIcon active={props.active} />
        </span>
      </button>
      <PauseConfirmModal
        isOpen={isConfirmOpen}
        onCancel={() => setConfirmOpen(false)}
        onConfirm={handleConfirm}
      />
    </>
  );
}

function resolvePowerButtonLabel(
  stopRequested: boolean,
  canCancel: boolean,
): string {
  if (stopRequested && canCancel) return "Cancelar desligamento";
  if (stopRequested) return "Desligamento agendado";
  return ROBOT_COPY.powerButton.ariaLabel;
}

function powerButtonClassName(
  interactive: boolean,
  stopRequested: boolean,
  active: boolean,
): string {
  // #175-B coordination: classes/visual feedback owned by Opus B. The handler
  // (handleClick / setConfirmOpen / markInteraction* ordering) lives in
  // FlowStatusPowerButton above and is owned by Opus A. `active:scale-95`
  // fires on pointerdown — same frame as the click, no JS state.
  // Explicit arbitrary transition-property keeps the existing color/border
  // hover animations AND adds the transform animation in one declaration
  // (using `transition-transform` alone would override `transition-colors`).
  // motion-reduce kills both per a11y prefs.
  const base =
    "relative z-10 grid h-8 w-8 shrink-0 place-items-center justify-self-end rounded-full border transition-[transform,background-color,border-color,color,box-shadow] duration-150 motion-reduce:transition-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/55 active:scale-95 active:duration-75";
  if (stopRequested) {
    return cn(
      base,
      "border-rose-300/28 bg-rose-500/[0.16] text-rose-100 shadow-[0_8px_22px_rgba(127,29,29,0.24)]",
      interactive ? "hover:border-rose-200/36 hover:bg-rose-500/[0.2]" : "",
    );
  }
  if (active) {
    // R271: glow ciano reduzido (de 18px/0.16 → 10px/0.08) e bg/borda mais
    // sutis para o botão não disputar foco com o "AÇÃO RECOMENDADA"/"VENDA".
    return cn(
      base,
      "border-cyan-300/16 bg-cyan-400/[0.06] text-cyan-100/85 shadow-[0_0_10px_rgba(34,211,238,0.08)]",
      interactive
        ? "hover:border-rose-300/28 hover:bg-rose-400/[0.09] hover:text-rose-100"
        : "",
    );
  }
  if (interactive) {
    return cn(
      base,
      "border-white/8 bg-white/[0.035] text-white/50 shadow-[0_8px_22px_rgba(0,0,0,0.18)] hover:border-rose-300/22 hover:bg-rose-400/[0.07] hover:text-rose-100",
    );
  }
  return cn(
    base,
    "border-white/8 bg-white/[0.03] text-white/38 shadow-[0_8px_22px_rgba(0,0,0,0.12)]",
  );
}

function PowerIcon(props: { readonly active: boolean }): React.JSX.Element {
  // R271: anel girante removido. Operador: chamava atenção demais; a tinta
  // ciano do botão já comunica que o robô está ativo. Mantemos só um pulse
  // sutil no anel interno quando ativo (motion-reduce honra preferência).
  return (
    <>
      {props.active ? (
        <span
          aria-hidden="true"
          className="absolute inset-1 rounded-full border border-cyan-300/15 motion-safe:animate-[pulse_3.2s_ease-in-out_infinite] motion-reduce:opacity-60"
        />
      ) : null}
      <Power className="relative h-4 w-4" />
    </>
  );
}

function noop(): void {
  /* no-op fallback when the IA chip has no upsell route wired up */
}

function AiCellWithDropdown(props: {
  readonly selector: AiSelectorState;
  readonly onUpsellPro: () => void;
}): React.JSX.Element {
  return (
    <div
      className={cn(
        "flex h-[50px] shrink-0 flex-col items-center gap-1 overflow-visible",
        AI_STATUS_CELL_WIDTH_CLASS,
      )}
      data-testid="flow-status-ai-dropdown-wrap"
    >
      <span className="max-w-full text-[7px] font-semibold uppercase tracking-[0.22em] text-sky-100/58">
        IA
      </span>
      <AiModeStatusDropdown
        current={props.selector.current}
        hasPro={props.selector.hasPro}
        onSelectMode={props.selector.onSelect}
        onUpsellPro={props.onUpsellPro}
        busy={props.selector.busy === true}
        disabled={props.selector.disabled === true}
      />
    </div>
  );
}

function FlowStatusMetrics(props: {
  readonly bar: RobotFlowStatusBar;
  readonly stage: RobotVisualFlowStage;
}): React.JSX.Element {
  return (
    <div
      className="flex h-[50px] min-w-0 flex-1 items-end justify-between gap-0.5 overflow-hidden"
      data-testid="flow-status-metrics"
    >
      {/* R300 (issue #176-3): chip widths recalibrados para S8 360×740 base.
       *  Total horizontal interno do panel (após px-2.5×2 + power button h-8
       *  w-8 + gap-1.5): ~316px usáveis em 360. Larguras somam 196 (44+50+
       *  52+48 sem gaps), deixando ~120px de slack distribuído via justify-
       *  between — chips respiram sem encostar nem truncar. `min-[360px]:`
       *  adicionado entre base (320 iPhone SE) e min-[375px] (iPhone 14
       *  Pro) pra escala progressiva. `sm:` reduzido ~10-15px (era 88/80/
       *  68 → 76/72/60) — operador viu desperdício no desktop. */}
      <StatusMetric
        label="Status"
        value={FLOW_STAGE_STATUS_LABEL[props.stage]}
        tone="status"
        widthClassName="w-[44px] min-[360px]:w-[52px] min-[375px]:w-[60px] sm:w-[76px]"
        testId="flow-status-stage-cell"
      />
      {props.bar.tokensLabel !== null ? (
        <StatusMetric
          label="Tokens"
          value={props.bar.tokensLabel}
          tone="token"
          widthClassName="w-[50px] min-[360px]:w-[58px] min-[375px]:w-[72px] sm:w-[72px]"
          onClick={props.bar.onTokensClick}
          testId="flow-status-tokens-cell"
        />
      ) : (
        <span data-testid="flow-status-tokens-hidden" className="hidden" />
      )}
      <StatusMetric
        label="Plano"
        value={props.bar.planLabel}
        tone="plan"
        widthClassName="w-[52px] min-[360px]:w-[58px] min-[375px]:w-[62px] sm:w-[60px]"
        onClick={props.bar.onPlanClick}
        testId="flow-status-plano-cell"
      />
      {props.bar.aiSelector ? (
        <AiCellWithDropdown
          selector={props.bar.aiSelector}
          onUpsellPro={props.bar.onAiClick ?? noop}
        />
      ) : (
        <StatusMetric
          label="IA"
          value={props.bar.aiLabel}
          tone="ai"
          aiVariant={
            props.bar.aiLabel.toUpperCase().includes("PRO") ? "pro" : "basic"
          }
          widthClassName={AI_STATUS_CELL_WIDTH_CLASS}
          onClick={props.bar.onAiClick}
          testId="flow-status-ai-cell"
        />
      )}
    </div>
  );
}

// When `onClick` is provided the cell renders as an interactive button
// (DEV parity: TOKENS/PLANO chips open commerce upgrade offers). Without
// it the cell stays a non-interactive span — same visual, no a11y noise.
function StatusMetric(props: {
  readonly label: string;
  readonly tone: "ai" | "plan" | "status" | "token";
  readonly value: string;
  readonly aiVariant?: "pro" | "basic";
  readonly onClick?: (() => void) | undefined;
  readonly testId?: string | undefined;
  readonly widthClassName?: string | undefined;
}): React.JSX.Element {
  const tone = metricTone(props.tone, props.aiVariant);
  // R296 (28/05/2026): tentativa anterior com `[container-type:inline-size]`
  // no wrapper colapsou a flex-col em alguns navegadores e sumiu os chips
  // STATUS/TOKENS/PLANO inteiros — só IA sobrava. Abandonado e coberto por
  // regressão E2E (`status-bar-chips.spec.ts`). Voltamos pro `text-[8px]
  // sm:text-[9px]` base com `tracking-tighter` em sm: e padding lateral
  // reduzido pra "ILIMITADO" / "RESULTADO" caberem sem cortar.
  const valueClassName = cn(
    "inline-flex h-8 min-w-0 items-center justify-center overflow-hidden rounded-full border px-1.5 text-center sm:h-9 sm:px-2",
    "whitespace-nowrap text-[8px] font-semibold uppercase leading-[1.05] tracking-normal sm:text-[9px] sm:tracking-tighter",
    tone,
    props.widthClassName,
  );
  return (
    <div className="flex h-[50px] min-w-0 shrink-0 flex-col items-center gap-1 overflow-hidden">
      <span className={metricLabelClassName(props.tone)}>{props.label}</span>
      <StatusMetricValue
        value={props.value}
        className={valueClassName}
        onClick={props.onClick}
        testId={props.testId}
        label={props.label}
        tone={props.tone}
      />
    </div>
  );
}

function StatusMetricValue(props: {
  readonly value: string;
  readonly className: string;
  readonly onClick: (() => void) | undefined;
  readonly testId: string | undefined;
  readonly label: string;
  readonly tone: "ai" | "plan" | "status" | "token";
}): React.JSX.Element {
  if (!props.onClick) {
    return (
      <span
        className={props.className}
        data-testid={props.testId ?? "flow-status-value"}
      >
        <StatusMetricContent tone={props.tone} value={props.value} />
      </span>
    );
  }
  return (
    <button
      type="button"
      onClick={props.onClick}
      data-testid={props.testId}
      aria-label={`Abrir ofertas de ${props.label}`}
      className={cn(
        props.className,
        "cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/60",
      )}
    >
      <StatusMetricContent tone={props.tone} value={props.value} />
    </button>
  );
}

function StatusMetricContent(props: {
  readonly tone: "ai" | "plan" | "status" | "token";
  readonly value: string;
}): React.JSX.Element {
  if (props.tone === "status") {
    return <StatusMetricStateValue value={props.value} />;
  }
  if (props.tone === "ai") {
    return <StatusMetricAiValue value={props.value} />;
  }
  return (
    <span className="min-w-0 overflow-hidden text-ellipsis tabular-nums">
      {props.value}
    </span>
  );
}

function StatusMetricStateValue(props: {
  readonly value: string;
}): React.JSX.Element {
  return (
    <span className="inline-flex min-w-0 items-center gap-0.5 sm:gap-1">
      <span className="relative flex h-[5px] w-[5px] shrink-0">
        <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400/55" />
        <span className="relative inline-flex h-[5px] w-[5px] rounded-full bg-emerald-400" />
      </span>
      <span className="min-w-0 overflow-hidden text-ellipsis">
        {props.value}
      </span>
    </span>
  );
}

function StatusMetricAiValue(props: {
  readonly value: string;
}): React.JSX.Element {
  // Drop "IA " prefix: column header already reads "IA"; value is "PRO"/"BASIC".
  // ChevronDown removed — no inline picker exists behind this chip.
  // R268: justify-center mantém BASIC/PRO centrado mesmo quando o Sparkles
  // está hidden (mobile) — sem ele a label ficava deslocada à esquerda
  // dentro do pill (operador: "fica torto").
  return (
    <span className="inline-flex min-w-0 items-center justify-center gap-0.5 sm:gap-1">
      <Sparkles className="hidden h-2.5 w-2.5 shrink-0 text-current opacity-80 sm:block sm:h-3 sm:w-3" />
      <span className="shrink-0">{props.value}</span>
    </span>
  );
}

function metricTone(
  tone: "ai" | "plan" | "status" | "token",
  variant?: "pro" | "basic",
): string {
  if (tone === "token")
    return "border-teal-300/15 bg-[linear-gradient(180deg,rgba(20,184,166,0.08),rgba(13,23,29,0.82))] text-teal-50/92 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] hover:border-teal-200/22 hover:bg-[linear-gradient(180deg,rgba(45,212,191,0.1),rgba(13,23,29,0.86))]";
  if (tone === "plan")
    return "border-amber-200/15 bg-[linear-gradient(180deg,rgba(245,158,11,0.08),rgba(23,19,14,0.84))] text-amber-50/92 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] hover:border-amber-100/22 hover:bg-[linear-gradient(180deg,rgba(251,191,36,0.1),rgba(23,19,14,0.88))]";
  if (tone === "ai") {
    // Issue #186: status bar uses the contained legacy status-panel Pro tone.
    // The selector card keeps its larger outer glow; this compact chip cannot,
    // or S8 shows purple bleeding outside the pill edges.
    if (variant === "pro")
      return "border-fuchsia-400/22 bg-fuchsia-500/10 text-fuchsia-100 shadow-[inset_0_1px_0_rgba(255,255,255,0.05)]";
    return "border-cyan-300/16 bg-[linear-gradient(180deg,rgba(34,211,238,0.08),rgba(12,20,27,0.84))] text-cyan-50/92 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]";
  }
  return "border-emerald-400/10 bg-emerald-400/5 text-emerald-100 shadow-[0_0_8px_-4px_rgba(52,211,153,0.3)]";
}

function metricLabelClassName(
  tone: "ai" | "plan" | "status" | "token",
): string {
  const toneClassName =
    tone === "token"
      ? "text-teal-100/58"
      : tone === "plan"
        ? "text-amber-100/58"
        : tone === "ai"
          ? "text-sky-100/58"
          : "text-white/40";
  // R276: confirmado via medição (Playwright + getBoundingClientRect):
  // `tracking-[0.22em]` sozinho já centra o texto no box (offset 0). O
  // pl-[0.22em] que eu havia adicionado empurrava o texto +0.77px pra
  // direita, criando o desalinhamento que o operador via.
  return cn(
    "max-w-full text-[7px] font-semibold uppercase tracking-[0.22em]",
    toneClassName,
  );
}

