import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { TradeCardMiniChart } from "@/components/trade/TradeCardMiniChart";
import {
  canUpdateLastMiniCandle,
  createLegacyMiniChartOptions,
  createLegacyMiniSeriesOptions,
  toLegacyMiniChartData,
  toValidMiniChartCandle,
  type TradeMiniCandle,
} from "@/components/trade/trade-card-mini-chart-core";

const miniChartMocks = vi.hoisted(() => {
  const timeScaleApi = {
    getVisibleLogicalRange: vi.fn(() => ({ from: 0, to: 15 })),
    setVisibleLogicalRange: vi.fn(),
  };
  const seriesApi = {
    createPriceLine: vi.fn((options: unknown) => ({
      applyOptions: vi.fn(),
      options,
    })),
    removePriceLine: vi.fn(),
    priceToCoordinate: vi.fn((price: number) => 220 - price / 1_000),
    setData: vi.fn(),
    update: vi.fn(),
  };
  const chartApi = {
    addCandlestickSeries: vi.fn(() => seriesApi),
    applyOptions: vi.fn(),
    remove: vi.fn(),
    resize: vi.fn(),
    timeScale: vi.fn(() => timeScaleApi),
  };
  return {
    chartApi,
    createChart: vi.fn(() => chartApi),
    seriesApi,
    timeScaleApi,
  };
});

vi.mock("lightweight-charts", () => ({
  createChart: miniChartMocks.createChart,
  LineStyle: { Dashed: 2 },
}));

function miniCandleAt(index: number): TradeMiniCandle {
  const close = 64000 + index * 7;
  return {
    time: 1_777_280_400 + index * 60,
    open: close - 8,
    high: close + 12,
    low: close - 15,
    close,
  };
}

function renderMiniChart(
  candles: readonly TradeMiniCandle[],
  maxCandles?: number,
  visibleCandles?: number,
  minimumCandles?: number,
): ReturnType<typeof render> {
  return render(
    <TradeCardMiniChart
      candles={candles}
      direction="CALL"
      {...optionalMiniChartWindows(maxCandles, visibleCandles)}
      {...(minimumCandles === undefined ? {} : { minimumCandles })}
    />,
  );
}

function inconsistentCandle(): TradeMiniCandle {
  return {
    time: 1_777_280_400,
    open: 105,
    high: 103,
    low: 104,
    close: 101,
  };
}

function optionalMiniChartWindows(
  maxCandles: number | undefined,
  visibleCandles: number | undefined,
): { readonly maxCandles?: number; readonly visibleCandles?: number } {
  return {
    ...(maxCandles === undefined ? {} : { maxCandles }),
    ...(visibleCandles === undefined ? {} : { visibleCandles }),
  };
}

function installManualResizeObserver(): (width: number) => void {
  let resizeCallback: ResizeObserverCallback | null = null;
  class ManualResizeObserver implements ResizeObserver {
    constructor(callback: ResizeObserverCallback) {
      resizeCallback = callback;
    }
    disconnect(): void {}
    observe(): void {}
    unobserve(): void {}
  }
  vi.stubGlobal("ResizeObserver", ManualResizeObserver);
  return (width: number) => {
    if (!resizeCallback)
      throw new Error("ResizeObserver callback was not registered");
    resizeCallback([resizeObserverEntry(width)], {} as ResizeObserver);
  };
}

function resizeObserverEntry(width: number): ResizeObserverEntry {
  return {
    contentRect: { height: 228, width } as DOMRectReadOnly,
  } as ResizeObserverEntry;
}

describe("TradeCardMiniChart candle window", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    miniChartMocks.createChart.mockClear();
    miniChartMocks.chartApi.addCandlestickSeries.mockClear();
    miniChartMocks.chartApi.applyOptions.mockClear();
    miniChartMocks.chartApi.remove.mockClear();
    miniChartMocks.chartApi.resize.mockClear();
    miniChartMocks.chartApi.timeScale.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockClear();
    miniChartMocks.seriesApi.removePriceLine.mockClear();
    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();
    miniChartMocks.timeScaleApi.getVisibleLogicalRange.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it("keeps the legacy active-card window at 30 rendered and 15 visible candles", () => {
    const candles = Array.from({ length: 45 }, (_, index) =>
      miniCandleAt(index),
    );
    renderMiniChart(candles);
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "30");
    expect(chart).toHaveAttribute(
      "data-last-candle-close",
      String(candles.at(-1)?.close),
    );
    expect(chart).toHaveAttribute("data-max-candles", "30");
    expect(chart).toHaveAttribute("data-visible-candles", "15");
  });

  it("honors explicit candle windows for robot parity fixtures", () => {
    renderMiniChart(
      Array.from({ length: 20 }, (_, index) => miniCandleAt(index)),
      12,
      6,
    );
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "12");
    expect(chart).toHaveAttribute("data-max-candles", "12");
    expect(chart).toHaveAttribute("data-visible-candles", "6");
  });

  it("never paints a single-candle frame while history is still seeding", () => {
    // A single candle must not be painted — the component must wait for the
    // full minimumCandles window (default 30) before calling setData with data.
    renderMiniChart([miniCandleAt(0)]);
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "0");
    expect(chart).toHaveAttribute("data-min-candles", "30");
    expect(miniChartMocks.seriesApi.setData).not.toHaveBeenCalledWith(
      expect.arrayContaining([
        expect.objectContaining({ time: expect.any(Number) }),
      ]),
    );
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).not.toHaveBeenCalled();
    expect(screen.getByText("Carregando mercado...")).toBeInTheDocument();
  });

  it("reports an empty last close while the candle buffer is empty", () => {
    renderMiniChart([]);
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "0");
    expect(chart).toHaveAttribute("data-last-candle-close", "");
  });

  it("renders the full window the moment minimumCandles is met", () => {
    renderMiniChart(Array.from({ length: 30 }, (_, i) => miniCandleAt(i)));
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "30");
    expect(chart).toHaveAttribute("data-min-candles", "30");
    const setDataCalls = miniChartMocks.seriesApi.setData.mock.calls;
    const dataArg = setDataCalls.find(
      (call) => Array.isArray(call[0]) && call[0].length === 30,
    )?.[0];
    expect(dataArg).toHaveLength(30);
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).toHaveBeenCalledTimes(1);
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).toHaveBeenCalledWith({
      from: 14.8,
      to: 29.8,
    });
    expect(chart).toHaveAttribute("data-visual-ready", "true");
    expect(screen.queryByText("Carregando mercado...")).toBeNull();
  });

  it("seeds a fresh chart series with the full window after remount", () => {
    const firstSeries = {
      createPriceLine: vi.fn((options: unknown) => ({
        applyOptions: vi.fn(),
        options,
      })),
      removePriceLine: vi.fn(),
      priceToCoordinate: vi.fn((price: number) => 220 - price / 1_000),
      setData: vi.fn(),
      update: vi.fn(),
    };
    const secondSeries = {
      createPriceLine: vi.fn((options: unknown) => ({
        applyOptions: vi.fn(),
        options,
      })),
      removePriceLine: vi.fn(),
      priceToCoordinate: vi.fn((price: number) => 220 - price / 1_000),
      setData: vi.fn(),
      update: vi.fn(),
    };
    miniChartMocks.chartApi.addCandlestickSeries
      .mockReturnValueOnce(firstSeries)
      .mockReturnValueOnce(secondSeries);
    const candles = Array.from({ length: 30 }, (_, i) => miniCandleAt(i));

    const { rerender } = render(
      <TradeCardMiniChart
        assetSymbol="BTCUSDT"
        candles={candles}
        direction="CALL"
      />,
    );
    expect(firstSeries.setData).toHaveBeenCalledWith(
      expect.arrayContaining([
        expect.objectContaining({ time: expect.any(Number) }),
      ]),
    );

    rerender(
      <TradeCardMiniChart
        assetSymbol="ETHUSDT"
        candles={candles}
        direction="CALL"
      />,
    );

    expect(secondSeries.setData).toHaveBeenCalledWith(
      expect.arrayContaining([
        expect.objectContaining({ time: expect.any(Number) }),
      ]),
    );
    expect(secondSeries.setData.mock.calls.at(-1)?.[0]).toHaveLength(30);
    // PENDENCIAS contract: first paint is `setData` only — no `update` reinforce.
    // Live ticks call `update()` AFTER the historic window paints.
    expect(secondSeries.update).not.toHaveBeenCalled();
  });

  it("refocuses the painted full window after the chart container width settles", () => {
    const resize = installManualResizeObserver();
    renderMiniChart(Array.from({ length: 30 }, (_, i) => miniCandleAt(i)));

    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).toHaveBeenCalledTimes(1);
    act(() => resize(372));

    expect(miniChartMocks.chartApi.resize).toHaveBeenCalledWith(372, 228, true);
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).toHaveBeenCalledTimes(2);
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).toHaveBeenLastCalledWith({
      from: 14.8,
      to: 29.8,
    });
  });

  it("repaints the full window when focus returns after the chart was hidden", async () => {
    renderMiniChart(Array.from({ length: 30 }, (_, i) => miniCandleAt(i)));
    miniChartMocks.chartApi.resize.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();

    act(() => {
      document.dispatchEvent(new Event("visibilitychange"));
      window.dispatchEvent(new Event("focus"));
    });

    expect(miniChartMocks.chartApi.resize).toHaveBeenCalled();
    await waitFor(() => {
      expect(
        miniChartMocks.timeScaleApi.setVisibleLogicalRange,
      ).toHaveBeenCalledWith({
        from: 14.8,
        to: 29.8,
      });
    });
  });

  it("honors a custom minimumCandles prop", () => {
    const { rerender } = renderMiniChart(
      Array.from({ length: 5 }, (_, i) => miniCandleAt(i)),
      undefined,
      undefined,
      10,
    );
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-min-candles", "10");
    expect(chart).toHaveAttribute("data-candle-count", "0");
    expect(miniChartMocks.seriesApi.setData).not.toHaveBeenCalledWith(
      expect.arrayContaining([
        expect.objectContaining({ time: expect.any(Number) }),
      ]),
    );
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).not.toHaveBeenCalled();

    // Re-render with exactly 10 candles — threshold met, chart must paint.
    rerender(
      <TradeCardMiniChart
        candles={Array.from({ length: 10 }, (_, i) => miniCandleAt(i))}
        direction="CALL"
        minimumCandles={10}
      />,
    );
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-candle-count",
      "10",
    );
    expect(
      miniChartMocks.timeScaleApi.setVisibleLogicalRange,
    ).toHaveBeenCalledTimes(1);
  });

  it("holds a painted chart when partial data arrives after a full window", () => {
    // Prevents the "1-candle flash" where the parent's gate temporarily lets
    // short data through after a session drop or candle reset.
    const { rerender } = renderMiniChart(
      Array.from({ length: 30 }, (_, i) => miniCandleAt(i)),
    );
    // First render: full window — chart paints.
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-candle-count",
      "30",
    );
    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();

    // Re-render with only 1 candle — keep the prior full snapshot and do not
    // paint stale partial data or flash loading.
    rerender(
      <TradeCardMiniChart candles={[miniCandleAt(0)]} direction="CALL" />,
    );
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-candle-count",
      "0",
    );
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-visual-ready",
      "true",
    );
    expect(screen.queryByText("Carregando mercado...")).toBeNull();
    expect(miniChartMocks.seriesApi.setData).not.toHaveBeenCalled();
    expect(miniChartMocks.seriesApi.update).not.toHaveBeenCalled();
  });

  it.each([
    {
      cryptoIcon: "bitcoin",
      label: "BTC/USDT",
      symbol: "BTCUSDT",
    },
    {
      cryptoIcon: "ethereum",
      label: "ETH/USDT",
      symbol: "ETHUSDT",
    },
  ])(
    "renders $symbol pair identity in the chart chrome",
    ({ cryptoIcon, label, symbol }) => {
      render(
        <TradeCardMiniChart
          assetSymbol={symbol}
          candles={[miniCandleAt(0)]}
          direction="CALL"
        />,
      );
      expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
        "data-pair-label",
        label,
      );
      expect(screen.getByTestId("mini-chart-pair-badge")).toHaveTextContent(
        label,
      );
      const pairIcon = screen.getByTestId("mini-chart-pair-icon");
      expect(pairIcon.querySelector("svg")).toHaveAttribute(
        "data-crypto-icon",
        cryptoIcon,
      );
    },
  );

  it("uses flex vertical sizing when embedded in the active trade card", () => {
    render(
      <TradeCardMiniChart
        assetSymbol="BTCUSDT"
        candles={[miniCandleAt(0)]}
        direction="CALL"
        fillVerticalSpace
        height={320}
      />,
    );
    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-fill-vertical-space", "true");
    expect(chart).toHaveClass("h-full", "flex-1");
    expect(chart).not.toHaveStyle({ height: "320px" });
  });

  it("uses legacy compact chart chrome with visible right price scale band and DOM labels", () => {
    // R289: right native scale band is kept visible so candles do not
    // render under the DOM price-label pills. The dashed lines' rightward
    // continuation is rendered by a DOM strip behind the pills.
    const chartOptions = createLegacyMiniChartOptions(320, 190);
    const seriesOptions = createLegacyMiniSeriesOptions();
    expect(chartOptions.layout).toMatchObject({ attributionLogo: false });
    expect(chartOptions.rightPriceScale).toMatchObject({
      visible: true,
      borderVisible: false,
    });
    expect(chartOptions.timeScale).toMatchObject({
      visible: false,
      timeVisible: false,
    });
    expect(seriesOptions).toMatchObject({
      lastValueVisible: false,
      priceLineColor: "#00FF94",
      priceLineStyle: 2,
      priceLineVisible: true,
    });
  });
});

describe("TradeCardMiniChart price lines", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    miniChartMocks.createChart.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockClear();
    miniChartMocks.seriesApi.removePriceLine.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockImplementation(
      (options: unknown) => ({
        applyOptions: vi.fn(),
        options,
      }),
    );
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("creates the dashed entry line without a native axis label", () => {
    render(
      <TradeCardMiniChart
        candles={[miniCandleAt(0)]}
        currentPrice={64_120}
        direction="CALL"
        entryPrice={64_000}
      />,
    );

    expect(miniChartMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);
    expect(miniChartMocks.seriesApi.createPriceLine).toHaveBeenCalledWith(
      expect.objectContaining({
        axisLabelVisible: false,
        color: "#EAB308",
        lineStyle: 2,
        price: 64_000,
      }),
    );
  });

  it("renders overlap-safe DOM labels for entry and current price", async () => {
    render(
      <TradeCardMiniChart
        candles={Array.from({ length: 30 }, (_, index) => miniCandleAt(index))}
        currentPrice={64_000.01}
        direction="CALL"
        entryPrice={64_000}
      />,
    );

    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-price-label-current"),
      ).toHaveTextContent("64000.01");
      expect(
        screen.getByTestId("active-trade-price-label-entry"),
      ).toHaveTextContent("64000.00");
    });
  });

  it("updates the entry price line without recreating it", () => {
    const entryLine = { applyOptions: vi.fn(), options: {} };
    miniChartMocks.seriesApi.createPriceLine.mockReturnValueOnce(entryLine);
    const { rerender, unmount } = render(
      <TradeCardMiniChart
        candles={[miniCandleAt(0)]}
        direction="CALL"
        entryPrice={64_120}
      />,
    );
    expect(miniChartMocks.seriesApi.createPriceLine).toHaveBeenLastCalledWith(
      expect.objectContaining({ price: 64_120 }),
    );

    rerender(
      <TradeCardMiniChart
        candles={[miniCandleAt(0)]}
        direction="CALL"
        entryPrice={64_140}
      />,
    );
    expect(miniChartMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);
    expect(miniChartMocks.seriesApi.removePriceLine).not.toHaveBeenCalled();
    expect(entryLine.applyOptions).toHaveBeenCalledWith(
      expect.objectContaining({ price: 64_140 }),
    );

    unmount();
    expect(miniChartMocks.seriesApi.removePriceLine).toHaveBeenCalledTimes(1);
  });

  it("recreates the entry line after a chart series remount with the same price", async () => {
    const firstSeries = {
      createPriceLine: vi.fn((options: unknown) => ({
        applyOptions: vi.fn(),
        options,
      })),
      removePriceLine: vi.fn(),
      priceToCoordinate: vi.fn((price: number) => 220 - price / 1_000),
      setData: vi.fn(),
      update: vi.fn(),
    };
    const secondSeries = {
      createPriceLine: vi.fn((options: unknown) => ({
        applyOptions: vi.fn(),
        options,
      })),
      removePriceLine: vi.fn(),
      priceToCoordinate: vi.fn((price: number) => 220 - price / 1_000),
      setData: vi.fn(),
      update: vi.fn(),
    };
    miniChartMocks.chartApi.addCandlestickSeries
      .mockReturnValueOnce(firstSeries)
      .mockReturnValueOnce(secondSeries);
    const candles = Array.from({ length: 30 }, (_, i) => miniCandleAt(i));

    const { rerender } = render(
      <TradeCardMiniChart
        assetSymbol="BTCUSDT"
        candles={candles}
        direction="CALL"
        entryPrice={64_000}
      />,
    );
    expect(firstSeries.createPriceLine).toHaveBeenCalledWith(
      expect.objectContaining({ color: "#EAB308", price: 64_000 }),
    );

    rerender(
      <TradeCardMiniChart
        assetSymbol="ETHUSDT"
        candles={candles}
        direction="CALL"
        entryPrice={64_000}
      />,
    );

    await waitFor(() =>
      expect(secondSeries.createPriceLine).toHaveBeenCalledWith(
        expect.objectContaining({ color: "#EAB308", price: 64_000 }),
      ),
    );
  });

  it("removes the entry line when entry price becomes invalid", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={[miniCandleAt(0)]}
        direction="CALL"
        entryPrice={64_000}
      />,
    );
    expect(miniChartMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);

    rerender(
      <TradeCardMiniChart
        candles={[miniCandleAt(0)]}
        direction="CALL"
        entryPrice={Number.NaN}
      />,
    );
    expect(miniChartMocks.seriesApi.removePriceLine).toHaveBeenCalledTimes(1);
  });
});

describe("TradeCardMiniChart candle normalization", () => {
  it("normalizes Matrix OHLC before rendering each mini candle", () => {
    expect(toValidMiniChartCandle(inconsistentCandle())).toMatchObject({
      high: 105,
      low: 101,
      open: 105,
      close: 101,
    });
    expect(
      toValidMiniChartCandle({ ...miniCandleAt(0), close: Number.NaN }),
    ).toBeNull();
  });

  it("replaces invalid Matrix candles with a flat last-close candle", () => {
    const valid = miniCandleAt(0);
    const distorted = { ...miniCandleAt(1), low: 0 };

    expect(toLegacyMiniChartData([distorted], 3, 30)).toHaveLength(0);
    expect(toLegacyMiniChartData([valid, distorted], 3, 30)).toEqual([
      expect.objectContaining({ close: valid.close, low: valid.low }),
      expect.objectContaining({
        close: valid.close,
        high: valid.close,
        low: valid.close,
        open: valid.close,
      }),
    ]);
  });

  it("filters invalid candles after applying the rendered candle cap", () => {
    const candles = Array.from({ length: 4 }, (_, index) =>
      miniCandleAt(index),
    );
    const capped = toLegacyMiniChartData(
      [...candles, { ...miniCandleAt(4), close: Number.NaN }],
      3,
      30,
    );
    expect(capped).toHaveLength(3);
    expect(capped[0]?.time).toBe(candles[2]?.time);
    expect(capped[2]).toMatchObject({
      close: candles[3]?.close,
      high: candles[3]?.close,
      low: candles[3]?.close,
      open: candles[3]?.close,
    });
  });
});

describe("TradeCardMiniChart header layout", () => {
  it("renders trade badges above the chart canvas instead of overlaying it", () => {
    render(
      <TradeCardMiniChart
        assetSymbol="BTCUSDT"
        candles={[miniCandleAt(0)]}
        direction="PUT"
        headerContent={<div data-testid="trade-badges">VENDA ATUAL</div>}
        height={220}
      />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    const header = screen.getByTestId("active-trade-chart-header");
    const canvas = screen.getByTestId("active-trade-chart-canvas");
    expect(chart).toHaveClass("flex", "flex-col");
    expect(header).toContainElement(screen.getByTestId("trade-badges"));
    expect(canvas.compareDocumentPosition(header)).toBe(
      Node.DOCUMENT_POSITION_PRECEDING,
    );
  });
});

describe("TradeCardMiniChart incremental rendering", () => {
  it("uses last-candle update only when earlier OHLC values are unchanged", () => {
    const previous = toLegacyMiniChartData(
      [miniCandleAt(0), miniCandleAt(1), miniCandleAt(2)],
      30,
      30,
    );
    const nextLastOnly = toLegacyMiniChartData(
      [
        miniCandleAt(0),
        miniCandleAt(1),
        { ...miniCandleAt(2), close: miniCandleAt(2).close + 10 },
      ],
      30,
      30,
    );
    const nextHistoricalCorrection = toLegacyMiniChartData(
      [
        miniCandleAt(0),
        { ...miniCandleAt(1), high: miniCandleAt(1).high + 10 },
        { ...miniCandleAt(2), close: miniCandleAt(2).close + 10 },
      ],
      30,
      30,
    );

    expect(canUpdateLastMiniCandle(previous, nextLastOnly)).toBe(true);
    expect(canUpdateLastMiniCandle(previous, nextHistoricalCorrection)).toBe(
      false,
    );
  });
});

