import { describe, expect, it, vi } from "vitest";
import { fireEvent, render, screen } from "@testing-library/react";
import { AiModeStatusDropdown } from "./AiModeStatusDropdown";

describe("AiModeStatusDropdown (R250)", () => {
  it("renders current mode as BASIC pill by default", () => {
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={false}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    expect(screen.getByTestId("flow-status-ai-cell")).toHaveTextContent(
      "BASIC",
    );
    expect(screen.getByTestId("flow-status-ai-cell")).toHaveAttribute(
      "data-chip-tone",
      "ia-basic",
    );
    expect(screen.getByTestId("flow-status-ai-cell").className).toContain(
      "cyan",
    );
    expect(screen.getByTestId("flow-status-ai-cell").innerHTML).not.toContain(
      "text-ellipsis",
    );
  });

  it("renders PRO with contained legacy fuchsia tone (issue #186)", () => {
    render(
      <AiModeStatusDropdown
        current="pro"
        hasPro={true}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    expect(screen.getByTestId("flow-status-ai-cell")).toHaveTextContent("PRO");
    expect(screen.getByTestId("flow-status-ai-cell")).toHaveAttribute(
      "data-chip-tone",
      "ia-pro",
    );
    const className = screen.getByTestId("flow-status-ai-cell").className;
    expect(className).toContain("border-fuchsia-400/22");
    expect(className).toContain("bg-fuchsia-500/10");
    expect(className).toContain("shadow-[inset_0_1px_0");
    expect(className).not.toContain("shadow-[0_10px_30px");
    expect(screen.getByTestId("flow-status-ai-cell").innerHTML).not.toContain(
      "text-ellipsis",
    );
  });

  it("opens dropdown with Basic + Pro options on click", () => {
    const { container } = render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={true}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    expect(screen.getByTestId("flow-status-ai-cell")).toHaveAttribute(
      "aria-expanded",
      "true",
    );
    expect(screen.getByTestId("flow-status-ai-menu")).toBeInTheDocument();
    expect(container.querySelector('[data-testid="flow-status-ai-menu"]')).toBe(
      null,
    );
    expect(
      screen.getByTestId("flow-status-ai-option-basic"),
    ).toBeInTheDocument();
    expect(screen.getByTestId("flow-status-ai-option-pro")).toBeInTheDocument();
  });

  it("closes the menu on Escape", () => {
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={true}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    expect(screen.getByTestId("flow-status-ai-menu")).toBeInTheDocument();
    fireEvent.keyDown(document, { key: "Escape" });
    expect(screen.queryByTestId("flow-status-ai-menu")).toBeNull();
    expect(screen.getByTestId("flow-status-ai-cell")).toHaveAttribute(
      "aria-expanded",
      "false",
    );
  });

  it("closes the menu on outside click", () => {
    render(
      <div>
        <AiModeStatusDropdown
          current="basic"
          hasPro={true}
          onSelectMode={vi.fn()}
          onUpsellPro={vi.fn()}
        />
        <button type="button" data-testid="outside">
          outside
        </button>
      </div>,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    expect(screen.getByTestId("flow-status-ai-menu")).toBeInTheDocument();
    fireEvent.mouseDown(screen.getByTestId("outside"));
    expect(screen.queryByTestId("flow-status-ai-menu")).toBeNull();
  });

  it("selecting PRO without entitlement fires onUpsellPro (not onSelectMode)", () => {
    const onSelectMode = vi.fn();
    const onUpsellPro = vi.fn();
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={false}
        onSelectMode={onSelectMode}
        onUpsellPro={onUpsellPro}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    fireEvent.click(screen.getByTestId("flow-status-ai-option-pro"));
    expect(onUpsellPro).toHaveBeenCalledTimes(1);
    expect(onSelectMode).not.toHaveBeenCalled();
  });

  it("selecting PRO with entitlement fires onSelectMode('pro')", () => {
    const onSelectMode = vi.fn();
    const onUpsellPro = vi.fn();
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={true}
        onSelectMode={onSelectMode}
        onUpsellPro={onUpsellPro}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    fireEvent.click(screen.getByTestId("flow-status-ai-option-pro"));
    expect(onSelectMode).toHaveBeenCalledWith("pro");
    expect(onUpsellPro).not.toHaveBeenCalled();
  });

  it("selecting Basic always fires onSelectMode('basic') (even without entitlement)", () => {
    const onSelectMode = vi.fn();
    render(
      <AiModeStatusDropdown
        current="pro"
        hasPro={true}
        onSelectMode={onSelectMode}
        onUpsellPro={vi.fn()}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    fireEvent.click(screen.getByTestId("flow-status-ai-option-basic"));
    expect(onSelectMode).toHaveBeenCalledWith("basic");
  });

  it("Issue #170: Crown PRO no chip da statusbar fica ESTÁTICO (legacy parity)", () => {
    // Operador (28/05/2026): "n e pra pulsar no status bar a ia pro,
    // comportamento igual legacy". Pulse só na linha do dropdown.
    render(
      <AiModeStatusDropdown
        current="pro"
        hasPro={true}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    const cell = screen.getByTestId("flow-status-ai-cell");
    expect(cell.innerHTML).not.toMatch(/\banimate-pulse\b/);
  });

  it("renders the IA menu as a fixed overlay above the statusbar stacking context", () => {
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={true}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    const menu = screen.getByTestId("flow-status-ai-menu");
    expect(menu.className).toContain("z-[80]");
    expect(menu).toHaveAttribute("data-placement", "below");
    expect(menu).toHaveStyle({ position: "fixed" });
  });

  it("selecting the already-active mode does nothing", () => {
    const onSelectMode = vi.fn();
    const onUpsellPro = vi.fn();
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={false}
        onSelectMode={onSelectMode}
        onUpsellPro={onUpsellPro}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    fireEvent.click(screen.getByTestId("flow-status-ai-option-basic"));
    expect(onSelectMode).not.toHaveBeenCalled();
    expect(onUpsellPro).not.toHaveBeenCalled();
  });

  it("closes the menu after a selection", () => {
    render(
      <AiModeStatusDropdown
        current="basic"
        hasPro={true}
        onSelectMode={vi.fn()}
        onUpsellPro={vi.fn()}
      />,
    );
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    fireEvent.click(screen.getByTestId("flow-status-ai-option-pro"));
    expect(screen.queryByTestId("flow-status-ai-menu")).toBeNull();
  });
});

