import { render } from "@testing-library/react";
import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { TradeCardMiniChart } from "@/components/trade/TradeCardMiniChart";
import type { TradeMiniCandle } from "@/components/trade/trade-card-mini-chart-core";

const miniChartMocks = vi.hoisted(() => {
  const timeScaleApi = {
    getVisibleLogicalRange: vi.fn(() => ({ from: 0, to: 15 })),
    setVisibleLogicalRange: vi.fn(),
  };
  const seriesApi = {
    createPriceLine: vi.fn(() => ({ applyOptions: vi.fn() })),
    removePriceLine: vi.fn(),
    setData: vi.fn(),
    update: vi.fn(),
  };
  const chartApi = {
    addCandlestickSeries: vi.fn(() => seriesApi),
    applyOptions: vi.fn(),
    remove: vi.fn(),
    timeScale: vi.fn(() => timeScaleApi),
  };
  return {
    chartApi,
    createChart: vi.fn(() => chartApi),
    seriesApi,
    timeScaleApi,
  };
});

vi.mock("lightweight-charts", () => ({
  createChart: miniChartMocks.createChart,
  LineStyle: { Dashed: 2 },
}));

function miniCandle(index: number, valid = true): TradeMiniCandle {
  const close = 64000 + index * 7;
  if (!valid)
    return {
      time: 1_777_280_400 + index * 60,
      open: -1,
      high: -1,
      low: -2,
      close: -1,
    };
  return {
    time: 1_777_280_400 + index * 60,
    open: close - 8,
    high: close + 12,
    low: close - 15,
    close,
  };
}

// Deterministic PRNG — no Date.now, no Math.random — satisfies Repeatable (FIRST).
function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe("TradeCardMiniChart property invariants", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    miniChartMocks.createChart.mockClear();
    miniChartMocks.chartApi.addCandlestickSeries.mockClear();
    miniChartMocks.chartApi.applyOptions.mockClear();
    miniChartMocks.chartApi.remove.mockClear();
    miniChartMocks.chartApi.timeScale.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockClear();
    miniChartMocks.seriesApi.removePriceLine.mockClear();
    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();
    miniChartMocks.timeScaleApi.getVisibleLogicalRange.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  // New default threshold is 3 (MIN_CANDLES_FOR_TRADE_CHART = 3, P4 β/δ).
  // minimumCandlesOptions updated from [10, 12, 30] → [3, 10, 12] to reflect new baseline.
  it("setData is never called with non-empty length below minimumCandles across 200 random inputs", () => {
    const rand = mulberry32(42);
    const minimumCandlesOptions = [3, 10, 12] as const;

    for (let i = 0; i < 200; i++) {
      miniChartMocks.seriesApi.setData.mockClear();
      // Stub getContext fresh each iteration because cleanup restores mocks.
      vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
        {} as CanvasRenderingContext2D,
      );

      const inputLength = Math.floor(rand() * 51); // [0, 50]
      const validRatio = rand(); // [0, 1]
      const minimumCandles = minimumCandlesOptions[Math.floor(rand() * 3)]!; // pick one of three
      const maxCandles =
        minimumCandles === 3 ? 3 : Math.floor(rand() * 19) + 12; // [12, 30]

      const candles = Array.from({ length: inputLength }, (_, idx) =>
        miniCandle(idx, rand() < validRatio),
      );

      const { unmount } = render(
        <TradeCardMiniChart
          candles={candles}
          maxCandles={maxCandles}
          minimumCandles={minimumCandles}
          direction="CALL"
        />,
      );

      const setDataCalls = miniChartMocks.seriesApi.setData.mock.calls;
      const observedLengths = setDataCalls.map((c) =>
        Array.isArray(c[0]) ? (c[0] as unknown[]).length : -1,
      );

      for (const len of observedLengths) {
        if (len > 0 && len < minimumCandles) {
          expect.fail(
            JSON.stringify({
              inputLength,
              validRatio,
              minimumCandles,
              maxCandles,
              observedLengths,
            }),
          );
        }
      }

      unmount();
    }
  });

  it("series.update is never called on freshly-mounted empty series across 100 random inputs", () => {
    const rand = mulberry32(42);
    const minimumCandlesOptions = [3, 10, 12] as const;

    for (let i = 0; i < 100; i++) {
      miniChartMocks.seriesApi.update.mockClear();
      miniChartMocks.seriesApi.setData.mockClear();
      vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
        {} as CanvasRenderingContext2D,
      );

      const inputLength = Math.floor(rand() * 51);
      const validRatio = rand();
      const minimumCandles = minimumCandlesOptions[Math.floor(rand() * 3)]!;
      const maxCandles =
        minimumCandles === 3 ? 3 : Math.floor(rand() * 19) + 12;

      const candles = Array.from({ length: inputLength }, (_, idx) =>
        miniCandle(idx, rand() < validRatio),
      );

      // Fresh mount — previousData inside useMiniChartData starts as [].
      const { unmount } = render(
        <TradeCardMiniChart
          candles={candles}
          maxCandles={maxCandles}
          minimumCandles={minimumCandles}
          direction="CALL"
        />,
      );

      // update() must never fire on a freshly mounted chart with no prior data.
      expect(miniChartMocks.seriesApi.update).not.toHaveBeenCalled();

      unmount();
    }
  });
});

tests/unit/features/robot/FlowControlPan.source:
// FlowControlPanel: status ribbon (4-col) + StopBudget; isolated unit tests.
// Covers render gating, tones, click handlers (TOKENS/PLANO/Power), and the
// session-track positive/negative pin clamp logic.
import { describe, it, expect, vi } from "vitest";
import { fireEvent, render, screen } from "@testing-library/react";
import {
  FlowControlPanel,
  type RobotFlowStatusBar,
  type RobotFlowStopBudget,
} from "@/features/robot/components/flow/FlowControlPanel";
import type { RobotVisualFlowStage } from "@/features/robot/components/flow/robot-visual-flow";

const STATUS_BAR: RobotFlowStatusBar = {
  tokensLabel: "Ilimitado",
  planLabel: "365 dias",
  aiLabel: "PRO",
};

const STOP_BUDGET: RobotFlowStopBudget = {
  dailyProfitCents: 0,
  stopLossCents: 240_000,
  stopWinCents: 112_000,
  sessionProfitCents: 0,
};

type RenderOverrides = {
  stage?: RobotVisualFlowStage;
  statusBar?: RobotFlowStatusBar | undefined;
  stopBudget?: RobotFlowStopBudget | undefined;
  onStop?: () => void;
};

function renderPanel(overrides: RenderOverrides = {}): void {
  // WHY: explicit `in` check so passing `stopBudget: undefined` truly hides
  // the budget row (the default fallback would otherwise mask the gating bug).
  const statusBar = "statusBar" in overrides ? overrides.statusBar : STATUS_BAR;
  const stopBudget =
    "stopBudget" in overrides ? overrides.stopBudget : STOP_BUDGET;
  render(
    <FlowControlPanel
      stage={overrides.stage ?? "analyzing"}
      statusBar={statusBar}
      stopBudget={stopBudget}
      onStop={overrides.onStop}
    />,
  );
}

describe("FlowControlPanel — render gating", () => {
  it("returns null when both statusBar and stopBudget are absent", () => {
    const { container } = render(
      <FlowControlPanel
        stage="analyzing"
        statusBar={undefined}
        stopBudget={undefined}
        onStop={undefined}
      />,
    );
    expect(container.firstChild).toBeNull();
  });

  it("returns null when stage is stopped", () => {
    const { container } = render(
      <FlowControlPanel
        stage="stopped"
        statusBar={STATUS_BAR}
        stopBudget={STOP_BUDGET}
        onStop={vi.fn()}
      />,
    );
    expect(container.firstChild).toBeNull();
  });

  it("renders panel with status bar even when stopBudget is missing", () => {
    renderPanel({ stopBudget: undefined });
    expect(screen.getByTestId("flow-status-bar")).toBeInTheDocument();
    expect(screen.queryByTestId("flow-stop-budget")).toBeNull();
  });

  it("hides StopBudget for idle stage even when budget present", () => {
    renderPanel({ stage: "idle" });
    expect(screen.queryByTestId("flow-stop-budget")).toBeNull();
  });
});

describe("FlowControlPanel — status metric labels per stage", () => {
  it("maps stage to label (analyzing → ANÁLISE)", () => {
    renderPanel({ stage: "analyzing" });
    expect(screen.getByTestId("flow-status-metrics")).toHaveTextContent(
      /ANÁLISE/,
    );
  });

  it("maps signal stage to SINAL", () => {
    renderPanel({ stage: "signal" });
    expect(screen.getByTestId("flow-status-metrics")).toHaveTextContent(
      /SINAL/,
    );
  });

  it("maps active_trade stage to TRADE", () => {
    renderPanel({ stage: "active_trade" });
    expect(screen.getByTestId("flow-status-metrics")).toHaveTextContent(
      /TRADE/,
    );
  });

  it("renders tokensLabel/planLabel/aiLabel from props", () => {
    renderPanel();
    const metrics = screen.getByTestId("flow-status-metrics");
    expect(metrics).toHaveTextContent(/Ilimitado/);
    expect(metrics).toHaveTextContent(/365 dias/);
    // "IA " prefix was dropped from chip — column header already reads "IA".
    expect(metrics).toHaveTextContent(/PRO/);
  });

  it("renders legacy status dot and IA chip with Sparkles icon", () => {
    renderPanel({ stage: "active_trade" });
    const metrics = screen.getByTestId("flow-status-metrics");
    expect(metrics.querySelector(".animate-ping")).not.toBeNull();
    const aiCell = screen.getByTestId("flow-status-ai-cell");
    // Chip shows "PRO" only — no "IA PRO" double-label.
    expect(aiCell.textContent?.trim()).toBe("PRO");
    expect(aiCell.querySelector("svg")).not.toBeNull();
  });

  it("uses contained legacy Pro tone without outer purple bleed", () => {
    renderPanel({ stage: "active_trade" });
    const aiCell = screen.getByTestId("flow-status-ai-cell");
    expect(aiCell.className).toContain("border-fuchsia-400/22");
    expect(aiCell.className).toContain("bg-fuchsia-500/10");
    expect(aiCell.className).toContain("shadow-[inset_0_1px_0");
    expect(aiCell.className).not.toContain("shadow-[0_10px_30px");
  });

  it("renders aiLabel column as 'PRO' without 'IA' prefix", () => {
    renderPanel({ statusBar: { ...STATUS_BAR, aiLabel: "PRO" } });
    const aiCell = screen.getByTestId("flow-status-ai-cell");
    expect(aiCell.textContent?.trim()).toBe("PRO");
    expect(aiCell.textContent).not.toContain("IA PRO");
  });

  it("renders aiLabel column as 'BASIC' for free plan", () => {
    renderPanel({ statusBar: { ...STATUS_BAR, aiLabel: "BASIC" } });
    const aiCell = screen.getByTestId("flow-status-ai-cell");
    expect(aiCell.textContent?.trim()).toBe("BASIC");
    expect(aiCell.textContent).not.toContain("IA ");
    expect(aiCell.className).toContain("border-cyan-300/16");
    expect(aiCell.className).not.toContain("border-fuchsia");
  });

  it("clicking the IA cell triggers onAiClick", () => {
    const onAiClick = vi.fn();
    renderPanel({ statusBar: { ...STATUS_BAR, onAiClick } });
    fireEvent.click(screen.getByTestId("flow-status-ai-cell"));
    expect(onAiClick).toHaveBeenCalledTimes(1);
  });
});

describe("FlowControlPanel — interactive cells", () => {
  it("renders TOKENS cell as button when onTokensClick provided", () => {
    const onTokensClick = vi.fn();
    renderPanel({ statusBar: { ...STATUS_BAR, onTokensClick } });
    const cell = screen.getByTestId("flow-status-tokens-cell");
    expect(cell.tagName).toBe("BUTTON");
    fireEvent.click(cell);
    expect(onTokensClick).toHaveBeenCalledTimes(1);
  });

  it("renders TOKENS cell as span when onTokensClick is absent", () => {
    renderPanel();
    expect(screen.getByTestId("flow-status-tokens-cell").tagName).toBe("SPAN");
  });

  it("invokes onPlanClick when PLANO cell is clicked", () => {
    const onPlanClick = vi.fn();
    renderPanel({ statusBar: { ...STATUS_BAR, onPlanClick } });
    fireEvent.click(screen.getByTestId("flow-status-plano-cell"));
    expect(onPlanClick).toHaveBeenCalledTimes(1);
  });
});

describe("FlowControlPanel — power button", () => {
  it("renders inert span when onStop is undefined", () => {
    renderPanel({ stage: "idle" });
    expect(screen.getByTestId("flow-status-power").tagName).toBe("SPAN");
    expect(screen.getByTestId("flow-status-power").className).toContain(
      "border-white/8",
    );
    expect(screen.queryByTestId("flow-status-power-button")).toBeNull();
  });

  it("renders interactive button and fires onStop after confirm modal", () => {
    // R250: clicking the power button now opens a confirmation modal first;
    // onStop only fires when the operator confirms in PauseConfirmModal.
    const onStop = vi.fn();
    renderPanel({ onStop });
    const btn = screen.getByTestId("flow-status-power-button");
    fireEvent.click(btn);
    expect(onStop).not.toHaveBeenCalled();
    fireEvent.click(screen.getByTestId("pause-confirm-yes"));
    expect(onStop).toHaveBeenCalledTimes(1);
  });

  it("renders active running power chrome while the robot is operating", () => {
    const onStop = vi.fn();
    renderPanel({ stage: "active_trade", onStop });
    const btn = screen.getByTestId("flow-status-power-button");
    // R271: border foi suavizada de /28 → /16 e o anel girante virou pulse
    // discreto (operador: "girando ta chamando atenção demais").
    expect(btn.className).toContain("border-cyan-300/16");
    expect(btn.className).toContain("bg-cyan-400/[0.06]");
  });
});

describe("FlowControlPanel — StopBudget session track", () => {
  it("centers stop budget cells without text-right alignment", () => {
    renderPanel();
    for (const testId of [
      "flow-stop-budget-cell-loss",
      "flow-stop-budget-cell-win",
    ]) {
      const cell = screen.getByTestId(testId);
      expect(cell.className).toContain("items-center");
      expect(cell.className).not.toContain("text-right");
    }
  });

  it("positions cursor at the legacy asymmetric center when sessionProfitCents is zero", () => {
    renderPanel();
    const cursor = screen.getByTestId("flow-session-cursor") as HTMLElement;
    expect(Number.parseFloat(cursor.style.left)).toBeCloseTo(68.1818);
    expect(screen.getByTestId("flow-stop-budget")).toHaveAttribute(
      "data-profit-source",
      "session",
    );
    expect(screen.getByTestId("flow-stop-budget")).toHaveAttribute(
      "data-daily-profit-cents",
      "0",
    );
  });

  it("uses sessionProfitCents instead of dailyProfitCents for the HUD position", () => {
    renderPanel({
      stopBudget: {
        dailyProfitCents: 999_999,
        stopLossCents: 240_000,
        stopWinCents: 112_000,
        sessionProfitCents: 0,
      },
    });
    const cursor = screen.getByTestId("flow-session-cursor") as HTMLElement;
    expect(Number.parseFloat(cursor.style.left)).toBeCloseTo(68.1818);
    expect(screen.getByTestId("flow-stop-budget")).toHaveAttribute(
      "data-session-profit-cents",
      "0",
    );
  });

  it("clamps positive session profit at stopWin and uses legacy win classes", () => {
    renderPanel({
      stopBudget: {
        dailyProfitCents: -1,
        stopLossCents: 240_000,
        stopWinCents: 100_000,
        sessionProfitCents: 999_999,
      },
    });
    const cursor = screen.getByTestId("flow-session-cursor") as HTMLElement;
    expect(cursor.style.left).toBe("100%");
    expect(screen.getByTestId("flow-session-fill").className).toContain(
      "bg-emerald-400",
    );
    expect(screen.getByTestId("flow-session-fill").className).toContain(
      "rounded-r-full",
    );
    expect(screen.getByTestId("flow-session-profit-label").className).toContain(
      "text-emerald-50",
    );
  });

  it("clamps negative session profit at -stopLoss and uses legacy loss classes", () => {
    renderPanel({
      stopBudget: {
        dailyProfitCents: 999_999,
        stopLossCents: 100_000,
        stopWinCents: 100_000,
        sessionProfitCents: -999_999,
      },
    });
    const cursor = screen.getByTestId("flow-session-cursor") as HTMLElement;
    expect(cursor.style.left).toBe("0%");
    expect(screen.getByTestId("flow-session-fill").className).toContain(
      "bg-rose-500",
    );
    expect(screen.getByTestId("flow-session-fill").className).toContain(
      "rounded-l-full",
    );
    expect(screen.getByTestId("flow-session-profit-label").className).toContain(
      "text-rose-50",
    );
  });

  it("omits floating state when only one stop is configured", () => {
    renderPanel({
      stopBudget: {
        dailyProfitCents: 0,
        stopLossCents: 100_000,
        stopWinCents: 0,
        sessionProfitCents: 5_000,
      },
    });
    expect(screen.queryByTestId("flow-session-cursor")).toBeNull();
    expect(screen.queryByTestId("flow-session-fill")).toBeNull();
    expect(screen.queryByTestId("flow-session-profit-label")).toBeNull();
  });
});

