// Regression — guards the contract that the yellow dashed entry-price line
// spans the FULL chart width (no early termination, no DOM overlay).
//
// Operator-reported bug: in legacy DEV the entry line crosses the entire
// canvas; in v2 it sometimes terminated before the right edge OR was
// duplicated by a DOM overlay (`MiniChartEntryLine`) misaligned with the
// canvas price axis. The visual contract is:
//   - Single canvas line drawn by `series.createPriceLine` (dashed/style=2,
//     `axisLabelVisible: false`).
//   - No DOM element with `data-testid="mini-chart-entry-line"` (deprecated
//     overlay must stay removed).
//   - `rightPriceScale.visible: false` on the chart options so the line
//     spans the full width — when the right price scale is visible it
//     reserves a label band that truncates the price-line render at the
//     scale's left edge.
//   - The right-side DOM pills (`active-trade-price-label-entry`,
//     `active-trade-price-label-current`) carry the numeric values
//     instead.
//
// NOTE: this test was authored as a regression guard alongside the source
// fix in `createLegacyMiniChartOptions` (which already enforces
// `rightPriceScale.visible: false`). If a future change re-enables the
// native right price scale this test will FAIL — the canvas dashed line
// gets truncated by the reserved band and the operator-reported visual
// regression returns.

import { render, screen, waitFor } from "@testing-library/react";
import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { TradeCardMiniChart } from "@/components/trade/TradeCardMiniChart";
import type { TradeMiniCandle } from "@/components/trade/trade-card-mini-chart-core";

class NoopResizeObserver {
  observe(): void {
    return undefined;
  }
  unobserve(): void {
    return undefined;
  }
  disconnect(): void {
    return undefined;
  }
}

const entryLineMocks = vi.hoisted(() => {
  const timeScaleApi = {
    getVisibleLogicalRange: vi.fn(() => ({ from: 0, to: 15 })),
    setVisibleLogicalRange: vi.fn(),
  };
  const priceLineHandle = { applyOptions: vi.fn(), remove: vi.fn() };
  const seriesApi = {
    createPriceLine: vi.fn(() => priceLineHandle),
    removePriceLine: vi.fn(),
    setData: vi.fn(),
    update: vi.fn(),
    applyOptions: vi.fn(),
    priceToCoordinate: vi.fn(() => 110),
  };
  const chartApi = {
    addCandlestickSeries: vi.fn(() => seriesApi),
    applyOptions: vi.fn(),
    remove: vi.fn(),
    resize: vi.fn(),
    timeScale: vi.fn(() => timeScaleApi),
  };
  return {
    chartApi,
    createChart: vi.fn((_container: unknown, _options: unknown) => chartApi),
    priceLineHandle,
    seriesApi,
    timeScaleApi,
  };
});

vi.mock("lightweight-charts", () => ({
  createChart: entryLineMocks.createChart,
  LineStyle: { Solid: 0, Dotted: 1, Dashed: 2 },
}));

function buildCandle(index: number): TradeMiniCandle {
  // Deterministic close around the entry price so paint criteria
  // (`hasCompleteMiniChartData`) is satisfied with positive OHLC.
  const close = 74_980 + index * 3;
  return {
    time: 1_777_280_400 + index * 60,
    open: close - 6,
    high: close + 10,
    low: close - 12,
    close,
  };
}

function buildCandles(count: number): readonly TradeMiniCandle[] {
  return Array.from({ length: count }, (_, i) => buildCandle(i));
}

function clearEntryLineMocks(): void {
  entryLineMocks.createChart.mockClear();
  entryLineMocks.chartApi.addCandlestickSeries.mockClear();
  entryLineMocks.chartApi.applyOptions.mockClear();
  entryLineMocks.chartApi.remove.mockClear();
  entryLineMocks.chartApi.resize.mockClear();
  entryLineMocks.chartApi.timeScale.mockClear();
  entryLineMocks.seriesApi.createPriceLine.mockClear();
  entryLineMocks.seriesApi.removePriceLine.mockClear();
  entryLineMocks.seriesApi.setData.mockClear();
  entryLineMocks.seriesApi.update.mockClear();
  entryLineMocks.seriesApi.applyOptions.mockClear();
  entryLineMocks.priceLineHandle.applyOptions.mockClear();
  entryLineMocks.priceLineHandle.remove.mockClear();
  entryLineMocks.timeScaleApi.getVisibleLogicalRange.mockClear();
  entryLineMocks.timeScaleApi.setVisibleLogicalRange.mockClear();
}

describe("TradeCardMiniChart entry-line span contract", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    // jsdom has no ResizeObserver; the price-label measure hook needs one.
    vi.stubGlobal("ResizeObserver", NoopResizeObserver);
    // Drive rAF synchronously so label state settles before assertions.
    vi.spyOn(window, "requestAnimationFrame").mockImplementation((cb) => {
      cb(0);
      return 1;
    });
    vi.spyOn(window, "cancelAnimationFrame").mockImplementation(
      () => undefined,
    );
    // jsdom containers report 0x0 — give them a measurable rect so the label
    // layout has a non-zero chart height to work with.
    vi.spyOn(
      HTMLDivElement.prototype,
      "getBoundingClientRect",
    ).mockImplementation(
      () =>
        ({
          height: 160,
          width: 320,
          x: 0,
          y: 0,
          top: 0,
          left: 0,
          right: 320,
          bottom: 160,
          toJSON: () => ({}),
        }) as DOMRect,
    );
    Object.defineProperty(HTMLDivElement.prototype, "clientHeight", {
      configurable: true,
      get: () => 160,
    });
    Object.defineProperty(HTMLDivElement.prototype, "clientWidth", {
      configurable: true,
      get: () => 320,
    });
    clearEntryLineMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it("renders the entry line as a single dashed canvas line (createPriceLine call)", () => {
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // Exactly one entry-line createPriceLine call.
    expect(entryLineMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);

    const call = entryLineMocks.seriesApi.createPriceLine.mock.calls[0];
    if (!call) throw new Error("expected createPriceLine to be called");
    const lineOptions = (call as unknown as ReadonlyArray<unknown>)[0] as {
      readonly price: number;
      readonly lineStyle: number;
      readonly axisLabelVisible: boolean;
    };

    // Contract: line is anchored at the entry price, dashed, and MUST hide the
    // axis label — the right-side label is owned by the DOM pill instead so
    // the canvas line has nothing to truncate it.
    expect(lineOptions.price).toBe(75_000);
    expect(lineOptions.lineStyle).toBe(2);
    expect(lineOptions.axisLabelVisible).toBe(false);
  });

  it("does not render the deprecated mini-chart-entry-line DOM overlay", () => {
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    expect(
      screen.queryByTestId("mini-chart-entry-line"),
    ).not.toBeInTheDocument();
  });

  it("renders the right-side DOM pills for entry and current price", async () => {
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // Pills are mounted via an effect that runs after `isCanvasVisible` flips
    // true (post-`setVisualReady`). Wait for both testids to appear instead of
    // asserting synchronously.
    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-price-label-entry"),
      ).toBeInTheDocument();
      expect(
        screen.getByTestId("active-trade-price-label-current"),
      ).toBeInTheDocument();
    });
  });

  it("keeps rightPriceScale.visible=true so candles don't invade the label band", () => {
    // R289: rightPriceScale stays VISIBLE so lightweight-charts reserves
    // the right-edge band where the DOM price-label pills sit — without
    // this, candles render under the pills (operator: "as velas tão
    // invadindo onde era o campo dos valores"). The dashed-line truncation
    // is bridged by a DOM continuation strip rendered behind the pills, NOT
    // by hiding the native scale.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    expect(entryLineMocks.createChart).toHaveBeenCalled();
    const createCall = entryLineMocks.createChart.mock.calls[0];
    expect(createCall).toBeDefined();
    const options = createCall![1] as {
      readonly rightPriceScale?: { readonly visible?: boolean };
    };

    expect(options.rightPriceScale).toBeDefined();
    // CONTRACT: native right scale stays visible (band reserved). If this
    // flips to `false`, the candle-invasion regression returns.
    expect(options.rightPriceScale?.visible).toBe(true);
  });

  it("renders DOM continuation strips behind each price pill so dashed line has no visual gap", async () => {
    // R289/R291: with rightPriceScale.visible=true, lightweight-charts
    // reserves a band on the right where `createPriceLine` doesn't draw.
    // Two DOM `<span>` strips (one per pill — entry yellow + current green)
    // bridge that band visually. If these strips ever disappear, the
    // operator-reported "vão entre linha de entrada e vela" regression
    // returns and this test fails.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-price-label-entry-line-extension"),
      ).toBeInTheDocument();
      expect(
        screen.getByTestId("active-trade-price-label-current-line-extension"),
      ).toBeInTheDocument();
    });

    const entryStrip = screen.getByTestId(
      "active-trade-price-label-entry-line-extension",
    );
    const currentStrip = screen.getByTestId(
      "active-trade-price-label-current-line-extension",
    );
    // Each strip MUST carry the dashed repeating-linear-gradient + the
    // tone color so a CSS regression that drops the dashes or recolors them
    // breaks this test.
    expect(entryStrip.style.backgroundImage).toContain(
      "repeating-linear-gradient",
    );
    expect(entryStrip.style.backgroundImage).toContain("#EAB308");
    expect(currentStrip.style.backgroundImage).toContain(
      "repeating-linear-gradient",
    );
    expect(currentStrip.style.backgroundImage).toContain("#00FF94");
    // R292: strip width matches the lightweight-charts band (~56px). Wider
    // would extend INTO the candle area and double up with the canvas line.
    // Lower than 40 would leave a visible gap between line end and pill.
    const entryWidthPx = Number.parseInt(entryStrip.style.width, 10);
    expect(entryWidthPx).toBeGreaterThanOrEqual(40);
    expect(entryWidthPx).toBeLessThanOrEqual(72);
  });

  it("hides the canvas until focusRecentCandles has applied (no initial flash)", async () => {
    // R294: the operator-reported regression — on first paint the chart
    // briefly showed all 30 candles unfocused (with empty space between the
    // last candle and the entry line) before `focusRecentCandles` applied
    // the 10-candle window. The fix gates canvas opacity-100 on
    // `isVisualReady || hasPaintedSnapshot`, which only flips after 2 RAFs
    // (post-focus). `isCompleteData` alone — which used to short-circuit
    // visibility — is no longer enough.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // Wait for the visual ready gate to flip and apply opacity-100.
    await waitFor(() => {
      expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
        "data-visual-ready",
        "true",
      );
    });

    // Once visual-ready=true, the canvas wrapper exposes the chart and
    // focus has applied (we cannot inspect lightweight-charts internals
    // through the mock, but the gate is now equivalent to "focus done").
    expect(screen.getByTestId("active-trade-chart-canvas")).toBeInTheDocument();
  });

  it("canvas inner div starts opacity-0 and only flips to opacity-100 after focus settled", async () => {
    // R294 strong-guard: the operator demanded a hard regression test for
    // the candle-flash bug. The canvas's inner <div ref={containerRef}> is
    // the actual paint surface. Before `focusRecentCandles` + 2-RAF gate
    // settles, it MUST have opacity-0. Otherwise users see the unfocused
    // initial paint (all 30 candles squeezed, last candle far from entry
    // line) before the chart "fixes itself".
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // The canvas wrapper carries the test id; its only child is the
    // containerRef'd <div> with the opacity class.
    const canvasWrapper = screen.getByTestId("active-trade-chart-canvas");
    const innerCanvas = canvasWrapper.firstElementChild as HTMLElement | null;
    if (!innerCanvas) throw new Error("expected inner canvas div");

    await waitFor(() => {
      expect(innerCanvas.className).toContain("opacity-100");
    });
    // Sanity: never has opacity-0 once the focus has applied — we cannot
    // assert pre-flip in the same test because waitFor races the rAFs, but
    // we still pin the post-flip state so a regression that flips the
    // opacity logic backwards fails here.
    expect(innerCanvas.className).not.toContain("opacity-0");
  });

  it("MUST guarantee 1 createPriceLine call (no duplicate entry overlay) on first paint", async () => {
    // R294: extra paranoid guard — the deprecated DOM overlay
    // `mini-chart-entry-line` was removed because operators reported two
    // yellow lines. If a future change re-introduces a second
    // createPriceLine OR a DOM div with that testid, this guard blocks the
    // commit.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-chart-canvas"),
      ).toBeInTheDocument();
    });

    expect(entryLineMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);
    expect(
      screen.queryByTestId("mini-chart-entry-line"),
    ).not.toBeInTheDocument();
    // Both DOM continuation strips must exist — if either is missing, the
    // line truncates visibly before the pill (operator-reported gap).
    expect(
      screen.getByTestId("active-trade-price-label-entry-line-extension"),
    ).toBeInTheDocument();
    expect(
      screen.getByTestId("active-trade-price-label-current-line-extension"),
    ).toBeInTheDocument();
  });
});

// Legacy parity paint tests for TradeCardMiniChart (P4 Track E slice γ).
//
// Pins three behaviors that match legacy
// `quartel-bot/lib/charts/use-mini-trade-chart-series-data-sync.ts:96`
// (MIN_CANDLES_FOR_TRADE_CHART = 3):
// 1. Mounting with 3 candles paints once (`setData` length 3, `update` not called).
// 2. Adding one candle on top of a 3-candle prefix calls `update`, not a second `setData`.
// 3. Mounting with zero candles never paints — overlay is shown.
//
// Slice δ rewires `<TradeCardMiniChart>` to import the new
// `MIN_TRADE_CHART_CANDLES = 3` constant; on `main` the threshold is 30, so
// cases 1 and 2 fail (no setData fires under the legacy threshold).
//
// TODO: blocked on slice ε — fakes import path. The named factories
// `createFakeMiniChartRuntime` + `installFakeLightweightChartsModule` live in
// `tests/unit/_fakes/lightweight-charts.ts` (slice ε). Until ε merges,
// `pnpm typecheck` errors on these imports.
import {
  createFakeMiniChartRuntime,
  installFakeLightweightChartsModule,
} from "../../_fakes/lightweight-charts";

const fakeRuntime = createFakeMiniChartRuntime();
installFakeLightweightChartsModule(fakeRuntime);

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { render } from "@testing-library/react";
import type { TradeMiniCandle } from "@/components/trade/trade-card-mini-chart-core";
import type { TradeCardMiniChart as TradeCardMiniChartType } from "@/components/trade/TradeCardMiniChart";

type MiniChartComponent = typeof TradeCardMiniChartType;

function miniCandle(index: number, startTime = 1_777_280_400): TradeMiniCandle {
  const close = 64000 + index * 7;
  return {
    time: startTime + index * 60,
    open: close - 8,
    high: close + 12,
    low: close - 15,
    close,
  };
}

function makeCandles(count: number): readonly TradeMiniCandle[] {
  return Array.from({ length: count }, (_, i) => miniCandle(i));
}

beforeEach(() => {
  fakeRuntime.reset();
  Object.defineProperty(HTMLCanvasElement.prototype, "getContext", {
    value: () => ({}),
    writable: true,
    configurable: true,
  });
});

afterEach(() => {
  Object.defineProperty(HTMLCanvasElement.prototype, "getContext", {
    value: () => null,
    writable: true,
    configurable: true,
  });
});

describe("TradeCardMiniChart legacy paint (threshold 3)", () => {
  it("mount_with_3_candles_setData_called_once_with_3", async () => {
    const TradeCardMiniChart = await loadTradeCardMiniChart();
    render(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    expect(fakeRuntime.series.setDataCalls).toHaveLength(1);
    expect(fakeRuntime.series.setDataCalls[0]).toHaveLength(3);
    expect(fakeRuntime.series.updateCalls).toHaveLength(0);
  });

  it("rerender_adding_candle_calls_update_not_setData", async () => {
    const TradeCardMiniChart = await loadTradeCardMiniChart();
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(4)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    expect(fakeRuntime.series.setDataCalls).toHaveLength(1);
    expect(fakeRuntime.series.updateCalls).toHaveLength(1);
  });

  it("mount_with_zero_candles_never_calls_setData", async () => {
    const TradeCardMiniChart = await loadTradeCardMiniChart();
    const { container } = render(
      <TradeCardMiniChart
        candles={makeCandles(0)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    expect(fakeRuntime.series.setDataCalls).toHaveLength(0);
    expect(container.textContent).toMatch(/Carregando|Sem candles/);
  });
});

async function loadTradeCardMiniChart(): Promise<MiniChartComponent> {
  const module = await import("@/components/trade/TradeCardMiniChart");
  return module.TradeCardMiniChart;
}

import { render, screen } from "@testing-library/react";
import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { TradeCardMiniChart } from "@/components/trade/TradeCardMiniChart";
import type { TradeMiniCandle } from "@/components/trade/trade-card-mini-chart-core";

const miniChartMocks = vi.hoisted(() => {
  const timeScaleApi = {
    getVisibleLogicalRange: vi.fn(() => ({ from: 0, to: 15 })),
    setVisibleRange: vi.fn(),
    setVisibleLogicalRange: vi.fn(),
  };
  const seriesApi = {
    createPriceLine: vi.fn(() => ({ applyOptions: vi.fn() })),
    removePriceLine: vi.fn(),
    setData: vi.fn(),
    update: vi.fn(),
  };
  const chartApi = {
    addCandlestickSeries: vi.fn(() => seriesApi),
    applyOptions: vi.fn(),
    remove: vi.fn(),
    timeScale: vi.fn(() => timeScaleApi),
  };
  return {
    chartApi,
    createChart: vi.fn(() => chartApi),
    seriesApi,
    timeScaleApi,
  };
});

vi.mock("lightweight-charts", () => ({
  createChart: miniChartMocks.createChart,
  LineStyle: { Dashed: 2 },
}));

function miniCandle(index: number, valid = true): TradeMiniCandle {
  const close = 64000 + index * 7;
  if (!valid)
    return {
      time: 1_777_280_400 + index * 60,
      open: -1,
      high: -1,
      low: -2,
      close: -1,
    };
  return {
    time: 1_777_280_400 + index * 60,
    open: close - 8,
    high: close + 12,
    low: close - 15,
    close,
  };
}

describe("TradeCardMiniChart normalization gate", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    miniChartMocks.createChart.mockClear();
    miniChartMocks.chartApi.addCandlestickSeries.mockClear();
    miniChartMocks.chartApi.applyOptions.mockClear();
    miniChartMocks.chartApi.remove.mockClear();
    miniChartMocks.chartApi.timeScale.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockClear();
    miniChartMocks.seriesApi.removePriceLine.mockClear();
    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();
    miniChartMocks.timeScaleApi.getVisibleLogicalRange.mockClear();
    miniChartMocks.timeScaleApi.setVisibleRange.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  // New threshold is 3 (MIN_CANDLES_FOR_TRADE_CHART = 3, P4 β/δ).
  it("3 valid candles paint without overlay", () => {
    const candles = Array.from({ length: 3 }, (_, i) => miniCandle(i));
    render(
      <TradeCardMiniChart
        candles={candles}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "3");
    expect(chart).toHaveAttribute("data-visual-ready", "true");
    expect(screen.queryByText("Carregando mercado...")).toBeNull();

    const nonEmptyCalls = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls).toHaveLength(1);
    expect((nonEmptyCalls[0]![0] as unknown[]).length).toBe(3);
  });

  it("3 candles with last 1 invalid (negative close) get flat-filled and paint", () => {
    // Indices 0-1 valid, index 2 invalid — normalization flat-fills trailing invalid.
    const candles = Array.from({ length: 3 }, (_, i) => miniCandle(i, i < 2));
    render(
      <TradeCardMiniChart
        candles={candles}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "3");

    const nonEmptyCalls = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls).toHaveLength(1);
    const painted = nonEmptyCalls[0]![0] as Array<{ close: number }>;
    expect(painted).toHaveLength(3);

    // All painted entries must have a positive close (flat-filled from last valid).
    for (const candle of painted) {
      expect(candle.close).toBeGreaterThan(0);
    }
  });

  it("3 candles with first 1 leading invalid get flat-filled (using next valid) and paint", () => {
    // Index 0 invalid, indices 1-2 valid — pre-scan seeds lastValidClose from index 1.
    const candles = Array.from({ length: 3 }, (_, i) => miniCandle(i, i >= 1));
    render(
      <TradeCardMiniChart
        candles={candles}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    // All 3 candles survive normalization (leading invalid gets flat-filled, NOT dropped).
    expect(chart).toHaveAttribute("data-candle-count", "3");

    const nonEmptyCalls = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls).toHaveLength(1);
    expect((nonEmptyCalls[0]![0] as unknown[]).length).toBe(3);
  });

  it("3 candles all invalid → no paint, overlay shown", () => {
    const candles = Array.from({ length: 3 }, (_, i) => miniCandle(i, false));
    render(
      <TradeCardMiniChart
        candles={candles}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "0");
    expect(screen.getByText("Carregando mercado...")).toBeInTheDocument();

    const nonEmptyCalls = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls).toHaveLength(0);
  });

  it("30 candles with the same timestamp collapse to 1 and do not paint", () => {
    const candles = Array.from({ length: 30 }, (_, i) => ({
      ...miniCandle(i),
      time: 1_777_280_400,
    }));
    render(<TradeCardMiniChart candles={candles} direction="CALL" />);

    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "0");
    expect(chart).toHaveAttribute("data-raw-candle-count", "30");
    expect(chart).toHaveAttribute("data-normalized-candle-count", "1");

    const nonEmptyCalls = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls).toHaveLength(0);
  });

  it("holds previously painted data when the next window becomes incomplete", () => {
    const validCandles = Array.from({ length: 30 }, (_, i) => miniCandle(i));
    const duplicateCandles = validCandles.map((candle) => ({
      ...candle,
      time: 1_777_280_400,
    }));
    const { rerender } = render(
      <TradeCardMiniChart candles={validCandles} direction="CALL" />,
    );
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-candle-count",
      "30",
    );

    rerender(
      <TradeCardMiniChart candles={duplicateCandles} direction="CALL" />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-candle-count", "0");
    expect(chart).toHaveAttribute("data-normalized-candle-count", "1");
    expect(miniChartMocks.seriesApi.setData).not.toHaveBeenLastCalledWith([]);
    expect(screen.queryByText("Carregando mercado...")).toBeNull();
    expect(chart).toHaveAttribute("data-visual-ready", "true");
  });

  it("6 input with maxCandles=3, last 3 mixed invalid + valid stays at 3 normalized", () => {
    // 6 total, sliced to last 3. Within the slice, index 1 is invalid.
    const candles = Array.from({ length: 6 }, (_, i) => {
      const sliceIndex = i - 3; // sliceIndex 0-2 for the last 3
      if (sliceIndex >= 0 && sliceIndex === 1) {
        return miniCandle(i, false);
      }
      return miniCandle(i);
    });

    render(
      <TradeCardMiniChart candles={candles} maxCandles={3} direction="CALL" />,
    );

    const chart = screen.getByTestId("active-trade-chart");
    // Flat-fill handles the 1 invalid entry — total stays 3.
    expect(chart).toHaveAttribute("data-candle-count", "3");

    const nonEmptyCalls = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls).toHaveLength(1);
    expect((nonEmptyCalls[0]![0] as unknown[]).length).toBe(3);
  });
});

import { render, screen } from "@testing-library/react";
import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { TradeCardMiniChart } from "@/components/trade/TradeCardMiniChart";
import type { TradeMiniCandle } from "@/components/trade/trade-card-mini-chart-core";

const miniChartMocks = vi.hoisted(() => {
  const timeScaleApi = {
    getVisibleLogicalRange: vi.fn(() => ({ from: 0, to: 15 })),
    setVisibleLogicalRange: vi.fn(),
  };
  const seriesApi = {
    createPriceLine: vi.fn(() => ({ applyOptions: vi.fn() })),
    removePriceLine: vi.fn(),
    setData: vi.fn(),
    update: vi.fn(),
  };
  const chartApi = {
    addCandlestickSeries: vi.fn(() => seriesApi),
    applyOptions: vi.fn(),
    remove: vi.fn(),
    timeScale: vi.fn(() => timeScaleApi),
  };
  return {
    chartApi,
    createChart: vi.fn(() => chartApi),
    seriesApi,
    timeScaleApi,
  };
});

vi.mock("lightweight-charts", () => ({
  createChart: miniChartMocks.createChart,
  LineStyle: { Dashed: 2 },
}));

function miniCandle(index: number, valid = true): TradeMiniCandle {
  const close = 64000 + index * 7;
  if (!valid)
    return {
      time: 1_777_280_400 + index * 60,
      open: -1,
      high: -1,
      low: -2,
      close: -1,
    };
  return {
    time: 1_777_280_400 + index * 60,
    open: close - 8,
    high: close + 12,
    low: close - 15,
    close,
  };
}

function makeCandles(count: number): readonly TradeMiniCandle[] {
  return Array.from({ length: count }, (_, i) => miniCandle(i));
}

describe("TradeCardMiniChart chunked arrival", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    miniChartMocks.createChart.mockClear();
    miniChartMocks.chartApi.addCandlestickSeries.mockClear();
    miniChartMocks.chartApi.applyOptions.mockClear();
    miniChartMocks.chartApi.remove.mockClear();
    miniChartMocks.chartApi.timeScale.mockClear();
    miniChartMocks.seriesApi.createPriceLine.mockClear();
    miniChartMocks.seriesApi.removePriceLine.mockClear();
    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();
    miniChartMocks.timeScaleApi.getVisibleLogicalRange.mockClear();
    miniChartMocks.timeScaleApi.setVisibleLogicalRange.mockClear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  // New threshold is 3 (MIN_CANDLES_FOR_TRADE_CHART = 3, P4 β/δ).
  // At 5 candles the gate is already met, so the first render already paints.
  it("paints when data arrives 5 → 10 → 30", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(5)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(10)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(30)}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const setDataCalls = miniChartMocks.seriesApi.setData.mock.calls;
    const nonEmptyCalls = setDataCalls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );

    // At least one non-empty paint must have occurred (first at 5 candles).
    expect(nonEmptyCalls.length).toBeGreaterThanOrEqual(1);

    // No partial paint below the new threshold (3).
    for (const call of setDataCalls) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len === 0 || len >= 3).toBe(true);
    }

    expect(miniChartMocks.seriesApi.update).not.toHaveBeenCalled();
  });

  it("paints once the threshold (3) is crossed during 0 → 2 → 3 → 4 arrival", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(0)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(2)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(4)}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    const setDataCalls = miniChartMocks.seriesApi.setData.mock.calls;

    // No setData call should have a length between 1 and 2 (below new threshold).
    for (const call of setDataCalls) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len === 0 || len >= 3).toBe(true);
    }

    // The 3-candle step must produce a non-empty paint.
    const nonEmptyCalls = setDataCalls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect(nonEmptyCalls.length).toBeGreaterThanOrEqual(1);

    // After 4 candles: either setData(3+ sliced) or update(last-only change) is acceptable.
    const updateCount = miniChartMocks.seriesApi.update.mock.calls.length;
    const setDataCount = nonEmptyCalls.length;
    expect(updateCount + setDataCount).toBeGreaterThanOrEqual(1);
  });

  it("clears chart when data shrinks 3 → 1 → 3", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );

    // First render: threshold met — chart paints with 3.
    const firstNonEmpty = miniChartMocks.seriesApi.setData.mock.calls.find(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect((firstNonEmpty![0] as unknown[]).length).toBe(3);

    miniChartMocks.seriesApi.setData.mockClear();

    // Second render: only 1 candle — below minimumCandles(3). Keep the last
    // valid snapshot mounted instead of flashing the loading fallback.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(1)}
        direction="CALL"
        minimumCandles={3}
        isLoading
      />,
    );
    const callsAfterShrink = miniChartMocks.seriesApi.setData.mock.calls;

    for (const call of callsAfterShrink) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len).toBeGreaterThanOrEqual(3);
    }
    expect(screen.queryByText("Carregando mercado...")).toBeNull();
    expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
      "data-visual-ready",
      "true",
    );

    miniChartMocks.seriesApi.setData.mockClear();

    // Third render: 3 again — repaint with full window.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(3)}
        direction="CALL"
        minimumCandles={3}
      />,
    );
    expect(
      document.querySelector('[data-testid="active-trade-chart"]'),
    ).toHaveAttribute("data-candle-count", "3");
  });

  it("respects minimumCandles=12 override across 5 → 12 → 13", () => {
    const { rerender } = render(
      <TradeCardMiniChart
        candles={makeCandles(5)}
        minimumCandles={12}
        direction="CALL"
      />,
    );

    // At 5 candles (below minimumCandles=12): no non-empty paint.
    const callsAt5 = miniChartMocks.seriesApi.setData.mock.calls;
    for (const call of callsAt5) {
      const len = Array.isArray(call[0]) ? (call[0] as unknown[]).length : 0;
      expect(len).toBe(0);
    }

    // The root div must advertise the override.
    const { getByTestId } = {
      getByTestId: (id: string) =>
        document.querySelector(`[data-testid="${id}"]`)!,
    };
    const chart = getByTestId("active-trade-chart");
    expect(chart).toHaveAttribute("data-min-candles", "12");

    miniChartMocks.seriesApi.setData.mockClear();

    // At exactly 12 candles: gate met, paint occurs.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(12)}
        minimumCandles={12}
        direction="CALL"
      />,
    );
    const callsAt12 = miniChartMocks.seriesApi.setData.mock.calls;
    const nonEmptyAt12 = callsAt12.find(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    expect((nonEmptyAt12![0] as unknown[]).length).toBe(12);

    miniChartMocks.seriesApi.setData.mockClear();
    miniChartMocks.seriesApi.update.mockClear();

    // At 13 candles: either update (last-only change) or setData capped to maxCandles.
    rerender(
      <TradeCardMiniChart
        candles={makeCandles(13)}
        minimumCandles={12}
        direction="CALL"
      />,
    );
    const updateCount = miniChartMocks.seriesApi.update.mock.calls.length;
    const setDataNonEmpty = miniChartMocks.seriesApi.setData.mock.calls.filter(
      (c) => Array.isArray(c[0]) && (c[0] as unknown[]).length > 0,
    );
    // One of the two paths must have been taken.
    expect(updateCount + setDataNonEmpty.length).toBeGreaterThanOrEqual(1);
  });
});

